ApplyAuditActions
ApplyAuditActionsRequest → ApplyAuditActionsResponse
editor
AuditURL was removed: a site score is AuditPipelineService.RunAudit with score_only set, and the report is AuditRun.score_report. ApplyAuditActions audits a URL and maps the auto-applyable fix-artifacts into a server-local repository (stack-aware, idempotent). mode escalates from "plan" (dry-run, default, no side effects) to "apply"/"commit"/"pr". Copy/infra actions are returned as manual for human review, never applied.



Also uses StreamChunk, PaginationRequest, PaginationResponse, AssistantToolEvent, AssistantProposal, Channel.
// ContentSuggestion is one concrete content idea within a ChannelPrescription.
message ContentSuggestion {
  string title = 1;
  string description = 2;
  string cta = 3;
}

// ChannelPrescription is the AI's structured recommendation for a single
// channel — role in the overall strategy, priority, concrete content ideas,
// preferred CTA style, and the KPIs that matter for it.
message ChannelPrescription {
  Channel channel = 1;
  string role = 2;
  string priority = 3;
  repeated ContentSuggestion suggestions = 4;
  string cta_recommendation = 5;
  repeated string kpis = 6;
  // The review verdict on this prescription.
  // Only concur and unable-to-judge ever appear here: a dissented
  // prescription is withheld and lives only in Diagnostic.judgements.
  // Unset = not reviewed.
  runink.ui.judgement.v1.Judgement judgement = 7;
}

// DocumentPrescription is the AI's structured recommendation for a single
// document format — its role, priority, and concrete ideas.
message DocumentPrescription {
  string format = 1;
  string role = 2;
  string priority = 3;
  repeated ContentSuggestion suggestions = 4;
}

// BrandVisibilityInsight is a Generative-Engine-Optimization finding: how to
// shape the brand's lexical/semantic presence so generative-AI metasearch
// engines (AI Overviews, Perplexity, ChatGPT, etc.) recognise, surface, and
// cite the company in context — a distinct insight stream from the
// audience-targeting prescriptions above.
message BrandVisibilityInsight {
  // entity_authority | semantic_topics | answer_framing | lexical_relevance |
  // structured_data | authority_sources
  string dimension = 1;
  string insight = 2;               // what the diagnosis found about current AI-search visibility
  repeated string target_terms = 3; // entities/phrases/queries to own for AI-search lexical relevance
  repeated string actions = 4;      // concrete actions to raise generative-AI discoverability
  string rationale = 5;             // why this shapes brand awareness in AI/metasearch engines
  // The review verdict on this insight; see ChannelPrescription.judgement.
  runink.ui.judgement.v1.Judgement judgement = 6;
}

// AudienceSegment is one tier of a 360-degree audience map (e.g. decision
// makers, influencers, end users), with the areas/roles/technologies that
// define it.
message AudienceSegment {
  string level = 1;
  repeated string areas = 2;
  repeated string roles = 3;
  repeated string technologies = 4;
}

// CronogramTask is one task in the multichannel execution calendar.
message CronogramTask {
  int32 week = 1;
  Channel channel = 2;
  string task = 3;
  bool completed = 4;
}

// Diagnostic is a full multichannel business diagnostic report.
message Diagnostic {
  string id = 1;
  string user_id = 2;
  string business_name = 3;
  string industry = 4;
  string niche = 5;
  string target_audience = 6;
  string current_channels = 7;      // comma-separated active channels
  string competitors = 8;           // comma-separated competitor names
  string business_description = 9;  // user's free-form business description
  string website_url = 10;
  string positioning_analysis = 11;
  string swot_analysis = 12;
  string channel_recommendations = 13;
  string content_strategy = 14;
  string competitive_landscape = 15;
  string ai_opinion = 16;           // strategic opinion from the AI market-analyst
  string status = 17;               // "pending", "generating", "completed", "error"
  map metadata = 18;
  google.protobuf.Timestamp created_at = 19;
  google.protobuf.Timestamp updated_at = 20;
  // Structured breakdown of channel_recommendations/content_strategy above,
  // parsed into structured fields instead of left as free text for the client to
  // guess at. Populated by GenerateDiagnostic; empty on a freshly-created,
  // not-yet-generated Diagnostic.
  repeated ChannelPrescription channel_prescriptions = 21;
  repeated AudienceSegment audience_segments = 22;
  repeated CronogramTask cronogram = 23;
  // URLs/titles of the real sources (site, LinkedIn, web search results)
  // the AI actually grounded this diagnostic in.
  repeated string sources_used = 24;
  // Real, backend-verified actions taken during generation (e.g. "Scraped
  // live content from acme.com"), same convention as StreamChunk.agent_tasks
  // — streamed live during GenerateDiagnostic and persisted here so the
  // trace survives after generation finishes, not just visible mid-stream.
  repeated string agent_tasks = 25;
  // User's selected goals for the diagnostic
  repeated string goals = 26;
  repeated DocumentPrescription document_prescriptions = 27;
  // Generative-Engine-Optimization insights — how to shape brand awareness /
  // discoverability in AI metasearch engines via lexical relevance, split out
  // from the audience-targeting prescriptions above.
  repeated BrandVisibilityInsight brand_visibility = 28;
  // Every review verdict on this diagnostic's proposals
  // (channel prescriptions + brand-visibility insights), accepted AND
  // rejected, with counts. A dissented proposal appears
  // ONLY here (accepted=false), never in the lists above.
  // Unset = not reviewed.
  runink.ui.judgement.v1.JudgementSet judgements = 29;
}

