// ApplyAuditActionsRequest audits url and applies auto-fixable actions to the
// repo at repo_path. mode ∈ {plan,apply,commit,pr}; empty = plan (dry-run).
message ApplyAuditActionsRequest {
  string url = 1;
  string repo_path = 2;
  string profile = 3;
  string mode = 4;   // plan|apply|commit|pr
  string branch = 5; // default: seo/pulse-remediation
  string base = 6;   // default: main
}

// ApplyAuditActionsResponse reports the detected stack, the planned/applied file
// changes, the manual (copy/infra) actions left for review, and the git result.
message ApplyAuditActionsResponse {
  string stack = 1;
  double overall_score = 2;
  repeated PlannedChange changes = 3;
  repeated AuditAction manual = 4;
  ApplyGitResult git = 5;
  string pr_body = 6;
}

// PlannedChange is one file the agent would create/modify/skip.
message PlannedChange {
  string path = 1;
  string op = 2; // create|modify|skip
  string check_id = 3;
  string reason = 4;
}

// ApplyGitResult reports how far the git/PR step got, with manual instructions
// when credentials or gh are unavailable.
message ApplyGitResult {
  string branch = 1;
  bool committed = 2;
  bool pushed = 3;
  string pr_url = 4;
  string instructions = 5;
}

// AuditAction is a concrete remediation fix-artifact for a check: the actual
// content to apply (robots.txt, canonical tag, JSON-LD block, rewritten title,
// header config) plus where it goes and whether it's safe to auto-apply.
message AuditAction {
  string check_id = 1;
  string title = 2;
  string rationale = 3;
  string severity = 4;     // critical|high|medium|low
  string type = 5;         // file_create|head_insert|content_edit|header_config|manual
  string target_hint = 6;
  string artifact = 7;     // the concrete content/snippet to apply
  string confidence = 8;   // high|medium|low
  bool auto_apply = 9;
  double impact = 10;
}

AuditPipelineService
The one-phrase audit ("Audit example.com"): the user types a domain and the PULSE pages are populated from it, ending with research and leads. Each step of a run is tracked, owner scoped, and reported honestly: a step is done only when it produced results or recorded "0 found" from a source that actually answered. A run whose required step failed ends partial or failed, never completed.
pulse.v1.AuditPipelineService, declared in pulse.proto.



Method
Request → Response
Least role
Notes




RunAudit
RunAuditRequest → stream AuditProgress
editor
RunAudit starts (or attaches to, or resumes) the caller's audit of a domain and streams stage progress until the run ends. A second call for the same (caller, domain) while a run is active attaches to it; a call after a failed/partial run resumes from the first stage that is not done; a call within 24h of a completed run returns that run unless force is set. A score_only call is its own run: it never attaches to or replays a full audit (nor a full audit to it); see RunAuditRequest.score_only.


GetAuditRun
GetAuditRunRequest → AuditRun
viewer



ListAuditRuns
ListAuditRunsRequest → ListAuditRunsResponse
viewer



GetAuditAiVisibility
GetAuditAiVisibilityRequest → AuditAiVisibility
viewer
GetAuditAiVisibility returns what a run's genai_visibility stage measured, finding by finding, with the evidence for each.


GetAuditFindings
GetAuditFindingsRequest → AuditFindings
viewer
GetAuditFindings returns what a run found for the business: leads with their contacts, possible competitors, where it wins and loses against each, niches worth exploring and partners with their contacts. Each kind says whether it was found, found nothing, or was not measured.


DeleteAuditRuns
DeleteAuditRunsRequest → DeleteAuditRunsResponse
editor
DeleteAuditRuns deletes some of the caller's full audit runs, or every run of one domain but the newest (all_but_latest, with the domain typed back as confirm). Removed: each run, its stages, its findings, its AI-visibility rows and its content-gaps snapshot unless a campaign plan uses it. Kept: leads, campaigns, drafts, the diagnosis and the site-score history. A run still in flight is refused, never deleted.


GetAuditAudience
GetAuditAudienceRequest → AuditAudience
viewer
GetAuditAudience returns who a run found the business sells to and what it sells (the research inputs it saved), each with where it came from.



Also uses AuditAction.
// AuditReport is the full audit result: the output contract of the scoring
// engine. overall_score is the weighted mean of composites; benchmark_mode is
// "relative" or "absolute"; skipped_data_sources lists adapters the user could
// configure to raise coverage.
message AuditReport {
  string url = 1;
  google.protobuf.Timestamp audited_at = 2;
  double overall_score = 3;
  repeated AuditComposite composites = 4;
  repeated string skipped_data_sources = 5;
  string benchmark_mode = 6;
  repeated AuditRecommendation recommendations = 7;
  repeated AuditAction actions = 8;
}

// AuditComposite is one of the four scored dimensions. coverage is the fraction
// (0-1) of the composite's weight that was actually scored — a 90 at 0.4
// coverage is very different from a 90 at 1.0.
message AuditComposite {
  string id = 1;
  string label = 2;
  double score = 3;
  double weight = 4;    // normalized 0-1
  double coverage = 5;  // 0-1
  repeated AuditSignal signals = 6;
}

// AuditSignal is a scored signal within a composite.
message AuditSignal {
  string id = 1;
  double score = 2;
  double weight = 3;    // normalized 0-1 within its composite
  double coverage = 4;  // 0-1
  repeated AuditCheck checks = 5;
}

// AuditCheck is a single check's outcome. status is "scored" | "skipped" |
// "error"; mode is "relative" | "absolute" for benchmark checks (else empty).
message AuditCheck {
  string id = 1;
  double score = 2;
  string status = 3;
  string raw_value = 4;
  string notes = 5;
  string mode = 6;
}

// AuditRecommendation is a lowest-scoring check surfaced by global weighted
// impact (check_weight × signal_weight × composite_weight), so the biggest
// wins bubble up.
message AuditRecommendation {
  string check_id = 1;
  double score = 2;
  double impact = 3;
  string notes = 4;
}

message RunAuditRequest {
  string domain = 1; // "example.com", "https://example.com/…" — normalised server-side
  bool force = 2;    // start a fresh run even when a completed one is  counts = 5;
  string error = 6;   // set whenever status is failed (and on a failed/partial terminal event)
  AuditProvenance provenance_summary = 7;
  int32 queue_position = 8; // >0 while this step is waiting to start
  string run_status = 9;    // running | completed | partial | failed
  string domain = 10;
  string diagnostic_id = 11;
  bool attached = 12;       // this stream joined a run another call started
  int32 attempt = 13;
}

message AuditStage {
  string stage = 1;
  string status = 2;
  int32 attempt = 3;
  map counts = 4;
  string error = 5;
  string detail = 6;
  google.protobuf.Timestamp started_at = 7;
  google.protobuf.Timestamp finished_at = 8;
  // Not applicable to this run (an optional stage skipped for a reason that
  // is not a failure, e.g. no material was attached): neither finished nor
  // unfinished, and not counted in "N of M parts".
  bool not_applicable = 9;
}

message AuditRun {
  string id = 1;
  string domain = 2;
  string diagnostic_id = 3;
  string status = 4; // running | completed | partial | failed
  google.protobuf.Timestamp created_at = 5;
  google.protobuf.Timestamp finished_at = 6;
  repeated AuditStage stages = 7;
  // The site score the run's score stage saved; unset when it saved none.
  AuditReport score_report = 8;
  bool score_only = 9;
}

message GetAuditRunRequest {
  string run_id = 1;
}

message ListAuditRunsRequest {
  int32 limit = 1;   // default 20, max 100
  string domain = 2; // optional filter
}

message ListAuditRunsResponse {
  repeated AuditRun runs = 1;
}

message GetAuditAiVisibilityRequest {
  string run_id = 1;
}

// One AI-access requirement read from the site itself.
message AiAccessCheck {
  string kind = 1;         // the kind of requirement (a stable identifier)
  string item = 2;         // what was checked
  string state = 3;        // pass | fail | not_measured
  string evidence = 4;     // the line that decided it
  string evidence_url = 5;
  // The site-score check whose fix-artifact (in the score report's actions,
  // applied through ApplyAuditActions) fixes a failure; "" when none does.
  string fix_check_id = 6;
}

// One buyer question read on a search engine's own result page.
message AiAnswerCheck {
  string question = 1;
  string basis = 2;        // what the question was derived from
  string engine = 3;       // the engine whose page was read
  string serp_url = 4;     // that page
  // cited | not_cited | no_ai_answer | not_measured. not_measured is never
  // counted as not cited.
  string state = 5;
  string why = 6;          // set when not_measured
  repeated string sources = 7;          // the AI answer's cited links
  repeated string competitors_cited = 8; // cited hosts matching a named competitor
  repeated string other_cited = 9;       // every other cited host
  int32 organic_rank = 10;  // the brand's position among organic results; 0 = not among them
  int32 organic_count = 11; // organic results on the page as loaded; 0 = page not read
}

message AuditAiVisibility {
  string run_id = 1;
  string domain = 2;
  bool measured = 3;       // false: the stage stored nothing (absent, not empty)
  repeated AiAccessCheck access = 4;
  repeated AiAnswerCheck answers = 5;
  string engines_covered = 6;  // e.g. "DuckDuckGo"
  string not_covered = 7;      // what this measurement does not read
}

message GetAuditFindingsRequest {
  string run_id = 1; // "" = the caller's latest full audit
}

// FindingContact is what a page publishes about how to reach someone.
message FindingContact {
  string email = 1;
  string phone = 2;
  string website = 3;
  string linkedin = 4;
}

message AuditFinding {
  string kind = 1;        // lead | competitor | advantage | niche | partner
  string title = 2;       // the company, competitor, niche or partner
  string detail = 3;      // why, in plain words
  string source_url = 4;  // where it was found or measured
  string basis = 5;       // measured | named (by the owner) | judged (a proposal that passed review)
  FindingContact contact = 6;
  repeated string wins = 7;   // advantage: checks this business meets and the competitor does not
  repeated string losses = 8; // advantage: checks the competitor meets and this business does not
  string lead_id = 9;         // lead: its row on the Leads page
  string judgement = 10;      // judged: the review verdict
  bool measured = 11;         // false = this item could not be measured (detail says why)
  string id = 12;             // the finding's own id (a partner's automation target id)
}

// AuditFindingKind is one kind's state for the run.
message AuditFindingKind {
  string kind = 1;
  string state = 2;  // found | none_found | not_measured
  string why = 3;    // none_found / not_measured: the stage's own reason
  string stage = 4;  // the stage that produced it
}

message AuditFindings {
  string run_id = 1;
  string domain = 2;
  repeated AuditFinding findings = 3;
  repeated AuditFindingKind kinds = 4;
}

message DeleteAuditRunsRequest {
  repeated string run_ids = 1;  // the caller's runs to delete
  // Delete every run of domain except its newest; confirm must equal the
  // domain as ListAuditRuns returns it (the typed confirmation).
  bool all_but_latest = 2;
  string domain = 3;
  string confirm = 4;
  // With all_but_latest: delete the newest run too.
  bool include_latest = 5;
  // START OVER (Settings › Account, Brand Analysis history): every run of the
  // caller (this account or agency client only) AND what the runs produced —
  // stages, findings, AI-visibility rows, site scores, insight snapshots
  // (content gaps, scenarios), every diagnosis, follow-up cycles with their
  // tasks and check-ins, market research (summaries, channels, trending posts,
  // imported partners), campaign proposals never accepted with their
  // campaigns, drafts never approved with their scheduled rows, creative
  // briefs and course outlines the audits made, and the leads they found.
  // confirm must equal domain, a domain the caller audited. Refused while any
  // of the caller's audits is running. Never deleted: anything published,
  // measured results (post_results), integrations, leads added by hand,
  // imported or won.
  bool start_over = 6;
  // Start over also deletes accepted campaigns (with their plans and roadmap).
  bool also_accepted_campaigns = 7;
  // No longer read: start over always deletes the leads audits found
  // (source "scraped" or linked from a finding) unless won (owner, 2026-10-30).
  bool also_audit_leads = 8;
  // Start over also deletes approved or scheduled items not sent yet.
  bool also_approved_unsent = 9;
  // Count what would go, delete nothing (the dialog's preview).
  bool dry_run = 10;
}

// What DeleteAuditRuns removed, row by row.
message DeleteAuditRunsResponse {
  repeated string deleted_run_ids = 1;
  int32 stages = 2;
  int32 findings = 3;
  int32 ai_visibility = 4;
  int32 snapshots = 5;
  // Runs still in flight: never deleted.
  repeated string refused_run_ids = 6;
  // Start over only (0 for a plain delete).
  int32 campaign_plans = 7;
  int32 campaigns = 8;
  int32 drafts = 9;          // content rows never approved
  int32 approved_unsent = 10; // approved or scheduled, not sent (only when asked)
  int32 scheduled_posts = 11; // pending scheduled posts removed with them
  int32 leads = 12;          // only when asked
  int32 roadmap_items = 13;
  int32 planner_tasks = 14;
  int32 diagnostics = 15;
  int32 competitor_channels = 16;
  // Published items kept (never deleted), for the dialog's summary.
  int32 kept_published = 17;
  bool dry_run = 18;
  // Start over refused: an audit is running (its run id).
  string refused_running = 19;
  int32 trending_posts = 20;   // trending posts the research saved for the runs' niches
  // Start over (owner, 2026-10-30: "clear everything the audits produced").
  int32 cycles = 21;            // follow-up cycles the audits made, with their tasks
  int32 check_ins = 22;         // the weekly check-ins of those cycles
  int32 creatives = 23;         // creative briefs the audits made
  int32 courses = 24;           // course outlines the audits made
  int32 market_summaries = 25;  // radar summaries
  int32 partners = 26;          // partners imported from the research (hand-added ones stay)
  int32 site_scores = 27;       // site scores the runs saved
  // What stays, for the dialog: leads added by hand, imported or won;
  // accepted campaigns (only when the person keeps them); connected accounts.
  int32 kept_leads = 28;
  int32 kept_campaigns = 29;
  int32 kept_integrations = 30;
}

message GetAuditAudienceRequest {
  string run_id = 1;
}

// One group of people the business sells to, as the run found them.
message AudiencePersona {
  string name = 1;
  string source = 2;   // tuning | owner | leads | audience
  string evidence = 3; // the line it was drawn from ("" when none was kept)
}

// One thing the business sells, in the site's own words when read there.
message AudienceOffering {
  string name = 1;
  string quote = 2;      // the site's words ("" when the owner typed it)
  string source = 3;     // site | tuning
  string source_url = 4; // the page read ("" for the owner's own words)
}

message AuditAudience {
  string run_id = 1;
  string domain = 2;
  // false: the run saved no audience (absent, not empty).
  bool measured = 3;
  repeated AudiencePersona personas = 4;
  repeated AudienceOffering offerings = 5;
  repeated string problems = 6; // the problems the research found for them
}

AuditAttachmentService
The material a person gives the new-site audit besides text: photos or a short video of the store or product, product documents (PDF, DOCX, TXT, MD) and voice notes. PULSE audits the brand AGAINST that material: does the site say what the documents and photos show, what is inconsistent, which benefits are not communicated.
UPLOAD IS CHUNKED OVER UNARY RPCS (Begin → Chunk… → Finish) because the web client speaks gRPC-Web, which has no client streaming. Every call is owner scoped: an upload or attachment of another user is NOT_FOUND. Bytes are stored encrypted the moment Finish accepts them; nothing is ever written to disk in plaintext. Pass the returned ids in AuditTuning.attachment_ids; an attachment used by a run lives as long as that run, one never used expires (expires_at).
pulse.v1.AuditAttachmentService, declared in attachments.proto.



Method
Request → Response
Least role
Notes




GetAttachmentLimits
GetAttachmentLimitsRequest → AttachmentLimits
viewer
What this instance accepts and can understand. Read it before showing the pickers: an instance that cannot look at photos still accepts them but says up front that it cannot.


BeginAttachmentUpload
BeginAttachmentUploadRequest → BeginAttachmentUploadResponse
editor
Declares a file. Refused (INVALID_ARGUMENT, with a sentence the UI can show) when its type is not accepted or its declared size is over the cap.


UploadAttachmentChunk
UploadAttachmentChunkRequest → UploadAttachmentChunkResponse
editor
Appends one chunk at offset (must equal the bytes received so far; a retried chunk at an already-received offset is acknowledged, not duplicated). At most max_chunk_bytes per call.


FinishAttachmentUpload
FinishAttachmentUploadRequest → AuditAttachment
editor
Checks the received bytes (size, sha256 when given, real file type, pages/duration caps), stores them and returns the attachment. Extraction then runs in the background: poll GetAttachment until status is not PROCESSING. Documents are usually READY on return.


GetAttachment
GetAttachmentRequest → AuditAttachment
viewer



ListAttachments
ListAttachmentsRequest → ListAttachmentsResponse
viewer



DeleteAttachment
DeleteAttachmentRequest → DeleteAttachmentResponse
editor
Removes the stored bytes and the extracted text. Idempotent.



enum AttachmentKind {
  ATTACHMENT_KIND_UNSPECIFIED = 0;
  ATTACHMENT_KIND_IMAGE = 1;    // jpeg, png, webp
  ATTACHMENT_KIND_VIDEO = 2;    // mp4, webm (short)
  ATTACHMENT_KIND_DOCUMENT = 3; // pdf, docx, txt, md
  ATTACHMENT_KIND_AUDIO = 4;    // a voice note: wav, webm/ogg opus, m4a, mp3
}

enum AttachmentStatus {
  ATTACHMENT_STATUS_UNSPECIFIED = 0;
  ATTACHMENT_STATUS_PROCESSING = 1; // stored; extraction still running
  ATTACHMENT_STATUS_READY = 2;      // done; see analysis for what was obtained
  ATTACHMENT_STATUS_FAILED = 3;     // stored, but nothing could be read (see detail)
}

// What PULSE could actually get out of the file. Three of these are honest
// "could not" states, never a guess: an image that cannot be looked at is
// IMAGE_UNDERSTANDING_UNAVAILABLE, never a description made up from a
// filename.
enum AttachmentAnalysis {
  ATTACHMENT_ANALYSIS_UNSPECIFIED = 0;
  ATTACHMENT_ANALYSIS_PENDING = 1;
  ATTACHMENT_ANALYSIS_TEXT_EXTRACTED = 2;   // document text read
  ATTACHMENT_ANALYSIS_NO_TEXT_FOUND = 3;    // read fine, but no text in it (e.g. a scanned PDF)
  ATTACHMENT_ANALYSIS_IMAGE_DESCRIBED = 4;  // the image (or video) was described
  ATTACHMENT_ANALYSIS_IMAGE_UNDERSTANDING_UNAVAILABLE = 5; // this instance cannot look at images, or it did not answer
  ATTACHMENT_ANALYSIS_FRAMES_NOT_ANALYSED = 6;  // video stored, but its content could not be analysed
  ATTACHMENT_ANALYSIS_TRANSCRIBED = 7;      // voice note transcribed
  ATTACHMENT_ANALYSIS_TRANSCRIPTION_UNAVAILABLE = 8; // this instance cannot transcribe, or it did not answer
  ATTACHMENT_ANALYSIS_FAILED = 9;           // the file could not be parsed
}

message GetAttachmentLimitsRequest {}

message AttachmentTypeLimit {
  AttachmentKind kind = 1;
  repeated string content_types = 2; // accepted MIME types
  repeated string extensions = 3;    // accepted extensions, lower case, no dot
  int64 max_bytes = 4;
  int32 max_duration_seconds = 5;    // video/audio; 0 = not applicable
  int32 max_pages = 6;               // documents; 0 = not applicable
}

message AttachmentLimits {
  repeated AttachmentTypeLimit types = 1;
  int32 max_attachments_per_audit = 2;
  int32 max_chunk_bytes = 3;
  // Whether the instance can look inside the material, decided from its
  // configuration. False is
  // shown to the person before they upload.
  bool image_understanding_available = 4;
  bool transcription_available = 5;
  bool video_frames_available = 6;
  int32 unused_retention_hours = 7; // an attachment no run used is removed after this
}

message BeginAttachmentUploadRequest {
  string filename = 1;     // shown back and cited in findings; path parts are dropped
  string content_type = 2; // as the picker reports it; the bytes are checked at Finish
  int64 size_bytes = 3;    // declared total size; Finish refuses a different count
}

message BeginAttachmentUploadResponse {
  string upload_id = 1;
  AttachmentKind kind = 2;
  int32 max_chunk_bytes = 3;
  google.protobuf.Timestamp expires_at = 4; // an unfinished upload is dropped after this
}

message UploadAttachmentChunkRequest {
  string upload_id = 1;
  int64 offset = 2;
  bytes data = 3;
}

message UploadAttachmentChunkResponse {
  int64 received_bytes = 1;
}

message FinishAttachmentUploadRequest {
  string upload_id = 1;
  string sha256_hex = 2; // optional; checked when set
}

message AuditAttachment {
  string id = 1;
  string filename = 2;
  string content_type = 3; // as detected from the bytes
  AttachmentKind kind = 4;
  int64 size_bytes = 5;
  AttachmentStatus status = 6;
  AttachmentAnalysis analysis = 7;
  string detail = 8;          // one sentence for the person: what was read, or why not
  string summary = 9;         // first part of what was extracted/described (bounded)
  int32 extracted_chars = 10; // size of the full extracted text the audit can use
  int32 page_count = 11;      // documents; 0 = unknown
  int32 duration_seconds = 12; // video/audio; 0 = unknown
  int32 frames_analysed = 13; // video: how much of it was analysed
  string audit_run_id = 14;   // the run that used it; "" = not used yet
  google.protobuf.Timestamp created_at = 15;
  google.protobuf.Timestamp expires_at = 16; // unset once a run uses it
  // What the audit run (audit_run_id) found comparing the site with this
  // material, each reviewed. Empty until that run's diagnosis.
  repeated AttachmentFinding findings = 17;
}

// One brand-vs-material finding drawn from an attachment.
message AttachmentFinding {
  string type = 1;      // gap | inconsistency | uncommunicated_benefit | confirmed
  string finding = 2;   // one sentence
  string action = 3;    // what to change on the site or in marketing
  string judgement = 4; // the review verdict text; "" = not reviewed
}

message GetAttachmentRequest {
  string attachment_id = 1;
}

message ListAttachmentsRequest {
  string audit_run_id = 1; // optional: only those a run used
}

message ListAttachmentsResponse {
  repeated AuditAttachment attachments = 1;
}

message DeleteAttachmentRequest {
  string attachment_id = 1;
}

message DeleteAttachmentResponse {
  bool deleted = 1; // false when there was nothing to delete
  // Whether the file is erased or hidden and still being erased.
  ErasureProgress erasure = 2;
}

// ErasureState is how far a deletion has got.
enum ErasureState {
  ERASURE_STATE_UNSPECIFIED = 0;
  // Erased; nothing is waiting.
  ERASURE_STATE_FINISHED = 1;
  // Hidden from you and being erased; nothing is needed from you.
  ERASURE_STATE_FINISHING = 2;
  // Hidden from you, not yet erased: it waits for your confirmation.
  ERASURE_STATE_NEEDS_CONFIRMATION = 3;
}

// ErasureProgress is the honest state of a deletion, in counts.
message ErasureProgress {
  ErasureState state = 1;
  // Items hidden and being erased.
  int32 finishing = 2;
  // Items hidden that wait for your confirmation.
  int32 needs_confirmation = 3;
}

