editor
Turn one idea into a campaign PROPOSAL (Campaigns: accept or dismiss).



enum BrandArea {
  BRAND_AREA_UNSPECIFIED = 0;
  BRAND_AREA_AWARENESS = 1;
  BRAND_AREA_REPUTATION = 2;
  BRAND_AREA_APPROVAL = 3;
}

message GetBrandSignalsRequest {
  BrandArea area = 1;
}

