  string campaign_id = 1;
  // Set when nothing new was proposed, and why.
  string note = 2;
}

message BrandSignalEvidence {
  string excerpt = 1;
  string source_url = 2;
  string source_label = 3;
}

message BrandSignalCard {
  string kind = 1;
  // positive | negative | mixed | neutral
  string tone = 2;
  string title = 3;
  string summary = 4;
  string suggestion = 5;
  // low | medium | high, and why.
  string confidence = 6;
  string confidence_reason = 7;
  repeated BrandSignalEvidence evidence = 8;
}

message BrandSignalSource {
  string label = 1;
  string url = 2;
  // read | not_readable | not_configured | failed
  string state = 3;
  string note = 4;
}

// One week's value of a measure.
message BrandMeasureWeek {
  string week = 1; // YYYY-MM-DD, a Monday
  double value = 2;
  int32 basis = 3;
}

// One measure: its latest value, what it rests on, and its own history.
message BrandMeasure {
  // visibility | mentions | rating | positive_share | approval
  string name = 1;
  double value = 2;
  // What the value rests on (pages, reviews, cited pieces); 0 = not measured.
  int32 basis = 3;
  // Why it was not measured, when basis is 0.
  string note = 4;
  // Oldest first; weeks with basis 0 are left out.
  repeated BrandMeasureWeek weeks = 5;
}

// A campaign idea from a measure's shift in its latest week against the
// account's own earlier weeks.
message BrandCampaignIdea {
  string idea_id = 1;
  string measure = 2;
  // up | down
  string direction = 3;
  string week = 4;
  double this_week = 5;
  double earlier_mean = 6;
  double earlier_min = 7;
  double earlier_max = 8;
  int32 earlier_weeks = 9;
  // 0 to 1; higher with more earlier weeks to compare against.
  double confidence = 10;
  string confidence_reason = 11;
  // The English rationale the proposal records.
  string rationale = 12;
  // Oldest first; the last is this week.
  repeated BrandMeasureWeek evidence = 13;
  // The campaign proposed from it ("" = not proposed).
  string campaign_id = 14;
}

message BrandSignals {
  BrandArea area = 1;
  // no_brand (no check-up names the brand) | not_read | read
  string state = 2;
  string brand_name = 3;
  // Why there are no cards, when there are none.
  string note = 4;
  google.protobuf.Timestamp read_at = 5;
  repeated BrandSignalCard cards = 6;
  repeated BrandSignalSource sources = 7;
  repeated BrandMeasure measures = 8;
  repeated BrandCampaignIdea ideas = 9;
  // Why there are no ideas (e.g. no earlier week yet).
  string ideas_note = 10;
  // Reputation and approvals: whether reviews PULSE holds were included.
  bool reviews_included = 11;
}

