  // none, queued (waiting for a person), sending, sent, rejected, failed.
  string reply_state = 4;
  // Why a reply waits or did not go: a fixed code.
  string reply_reason = 5;
  string class_code = 6;
  string company = 7;
  // The sentence the vendor wrote about what they sell, quoted.
  string offering = 8;
  string address = 9;
  string lang = 10;
  string draft_subject = 11;
  string draft_body = 12;
  google.protobuf.Timestamp created_at = 13;
  google.protobuf.Timestamp updated_at = 14;
  google.protobuf.Timestamp answered_at = 15;
  // The proposal to make this sender a lead: "", proposed, accepted, dismissed (a person decides).
  string lead_state = 16;
  string lead_id = 17;
  // What the sender sells, from a closed list; empty = not measured (a record from before insights).
  string category = 18;
}

message ListPartnerPitchesResponse {
  repeated PartnerPitch pitches = 1;
}

message DecidePartnerPitchRequest {
  string id = 1;
  // approve_reply (send the waiting reply now, through every gate),
  // edit_reply (replace the waiting body), reject_reply, set_stage.
  string action = 2;
  string draft_body = 3;
  string stage = 4;
  // The person confirms a My rules warning on the send.
  bool confirm_warning = 5;
  // Extra actions: accept_lead (make a lead from this sender, an internal record), dismiss_lead.
}

message GetVendorInsightsRequest {}

// One finding. code: top_category, rising_category, common_differentiator,
// pricing_model_mix, offering_overlap, offering_gap, counter_offer_reactions,
// channel_mix. subject is a closed-list code; count of of; evidence are record ids.
message VendorInsightEntry {
  string code = 1;
  string subject = 2;
  int32 count = 3;
  int32 of = 4;
  repeated string evidence = 5;
}

message VendorInsights {
  // False until the window and the minimum are set on the server.
  bool configured = 1;
  // Settings (environment names) still unset.
  repeated string missing = 2;
  int32 window_days = 3;
  int32 min_pitches = 4;
  // Pitches with insights inside the window.
  int32 evaluated = 5;
  // True when fewer than min_pitches were measured: no entries.
  bool abstained = 6;
  repeated VendorInsightEntry entries = 7;
  // The newest weekly digest and whether a person reviewed it ("" = none yet).
  string digest_week = 8;
  string digest_state = 9;
}

message ReviewVendorDigestRequest {
  string week = 1;
}

message SaveInboxReadingRequest {
  // Read the connected Gmail inbox for vendor pitches (DEFAULT OFF).
  bool enabled = 1;
  // Also read promotions, updates, social and forums (DEFAULT OFF; spam is never read).
  bool promotions = 2;
}

// What the inbox reader recorded, from facts only. state is one of: off, needs_vendor_switch, no_mailbox,
// gmail_only, reconnect_to_allow, rate_limited, provider_down, read_failed, daily_cap, waiting (switched
// on, nothing read yet) or reading. An unknown code is shown as itself.
message InboxReadingState {
  bool enabled = 1;
  bool promotions = 2;
  string state = 3;
  // Mail received before this is never looked at.
  google.protobuf.Timestamp enabled_at = 4;
  google.protobuf.Timestamp last_read_at = 5;
  // Last error code ("" = none) and, for a rate limit, when the next read may happen.
  string last_error = 6;
  google.protobuf.Timestamp retry_after = 7;
  // Messages by code: read, skipped_sent, skipped_spam, skipped_folder, skipped_before_switch_on and the
  // classes (vendor_pitch_competing, ... not_a_pitch, customer_or_lead, followup, skipped).
  repeated InboxReadCount counts = 8;
  int32 read_today = 9;
  int32 daily_cap = 10;
}

message InboxReadCount {
  string code = 1;
  int32 count = 2;
}

FirstResponseService
FIRST RESPONSE to a new website enquiry (owner request, 2026-11-27). For a NEW lead that arrives through the website form with a business email address, PULSE drafts a short acknowledgement from the account's own facts. Per-account switch, DEFAULT OFF. The default mode is a DRAFT waiting for one tap from a person; a second switch, also default off, lets the clearest cases go without the tap. Every send passes the same gates as an outreach email. One acknowledgement per lead, ever. The time from "received" to "first sent" is a measured fact kept as two timestamps; the response-time card reads it.
pulse.v1.FirstResponseService, declared in first_response.proto.



Method
Request → Response
Least role
Notes




GetFirstResponse
GetFirstResponseRequest → FirstResponseState
viewer
The caller's switches, what is missing before PULSE does anything, the acknowledgements waiting for a person and the measured response time.


SaveFirstResponse
SaveFirstResponseRequest → FirstResponseState
editor
Save the switches and the account's own words (person only).


DecideFirstResponse
DecideFirstResponseRequest → FirstResponseDraft
editor
A person's decision on one waiting acknowledgement: approve (runs every gate, attended), edit, or reject.



message GetFirstResponseRequest {}

message FirstResponseDraft {
  string lead_id = 1;
  // draft, sending, sent, rejected, skipped.
  string state = 2;
  // Why it waits or was skipped: a fixed code the app turns into a sentence.
  string reason_code = 3;
  string subject = 4;
  string body = 5;
  string address = 6;
  google.protobuf.Timestamp received_at = 7;
}

// The response-time card. Not measured is never shown as zero: measured is false
// and not_measured_codes say why (config_missing, too_few_leads).
message ResponseTime {
  bool measured = 1;
  repeated string not_measured_codes = 2;
  int32 window_days = 3;
  int32 min_leads = 4;
  // Leads in the window that were answered (the evidence).
  int32 answered = 5;
  int64 median_seconds = 6;
  int64 p90_seconds = 7;
  // Leads with no first response yet. With a threshold set, only those older than it;
  // without one, all of them (threshold_hours = 0).
  int32 unanswered = 8;
  int32 threshold_hours = 9;
}

message FirstResponseState {
  bool enabled = 1;
  bool auto_send = 2;
  // When a person will follow up, in the account's own words ("" = a neutral sentence).
  string wording = 3;
  // The account's own threshold for "unanswered", in hours; 0 = not set.
  int32 unanswered_after_hours = 4;
  // What the account still lacks before PULSE does anything: sender_identity,
  // postal_address, unsubscribe_link.
  repeated string missing = 5;
  repeated FirstResponseDraft waiting = 6;
  ResponseTime response_time = 7;
}

message SaveFirstResponseRequest {
  bool enabled = 1;
  bool auto_send = 2;
  string wording = 3;
  int32 unanswered_after_hours = 4;
}

message DecideFirstResponseRequest {
  string lead_id = 1;
  // approve_ack, edit_ack, reject_ack.
  string action = 2;
  string body = 3;
  bool confirm_warning = 4;
}

UnifiedInboxService
LEADS > INBOX (owner request, 2026-11-28): one READ-ONLY place that shows what PULSE has read and what it did about it, from every channel it reads (website form, the account's mailbox when inbox reading is on, replies to outreach, Instagram DMs), as rows of STRUCTURED FACTS and nothing else: the channel, when it was received, a closed class code, what PULSE did, who decided, the measured first-response time, and the id of the record that holds the rest. No message body, subject, snippet or address is ever in this service: the screen links to the record, which shows its own text on its own screen. Nothing is stored for it: every row is joined at read time from records that already exist.
pulse.v1.UnifiedInboxService, declared in unified_inbox.proto.



Method
Request → Response
Least role
Notes




GetUnifiedInbox
GetUnifiedInboxRequest → UnifiedInbox
viewer
The signed-in person's own handled messages, newest received first, paged by cursor, with the measured response time per channel. Read-only; any signed-in role that can read leads. A service account or a loop run reads nothing.



Also uses InboxReadCount, InboxReadingState.
message GetUnifiedInboxRequest {
  // "" = every channel, else website_form, email_inbox, outreach_reply or instagram_dm.
  string channel = 1;
  // "" = every state, else a closed InboxRow.action code.
  string action = 2;
  // Received at or after / before these (unset = no bound).
  google.protobuf.Timestamp since = 3;
  google.protobuf.Timestamp until = 4;
  // Rows per page: 0 means 50; more than 200 is 200.
  int32 limit = 5;
  // The previous page's next_page_token ("" = the first page).
  string page_token = 6;
}

// One thing PULSE read, as codes and times. Never text.
message InboxRow {
  // The row's own id: the record's id, prefixed with its kind.
  string id = 1;
  // website_form, email_inbox, outreach_reply, instagram_dm.
  string channel = 2;
  google.protobuf.Timestamp received_at = 3;
  // True when received_at is the time PULSE read the message (an older record
  // kept no receive time): the response time of such a row is not measured.
  bool received_is_read_time = 4;
  // The sender's class as a closed code: a vendor-pitch class (vendor_pitch_competing,
  // vendor_pitch_adjacent, prospect_signal, unable_to_judge, spam_or_phishing), the
  // lead's inbound status for a form lead, lead_reply for a reply to outreach, dm.
  string sender_code = 5;
  // What PULSE did: replied, held_for_person, skipped, spam_ignored, recorded,
  // waiting, failed.
  string action = 6;
  // The closed reason code behind a hold, a skip or a failure ("" = none).
  string reason_code = 7;
  // Who decided: pulse_rules (PULSE under the account's own rules), person, none_yet.
  string decided_by = 8;
  // The measured first-response time, received to first sent. Unset when not
  // measured: then response_not_measured says why (no_reply_sent, no_clock,
  // received_not_recorded). A measured time is never zero-filled.
  bool response_measured = 9;
  int64 response_seconds = 10;
  string response_not_measured = 11;
  // The record this row joins, by id only: lead, partner_pitch, engagement
  // or none (a message that was ignored or skipped before any record was made).
  string record_kind = 12;
  string record_id = 13;
  // The conscience trace of the check made before a send ("" = none was made):
  // the screen opens "What was checked" with it.
  string trace_action_id = 14;
}

message InboxCount {
  string code = 1;
  int32 count = 2;
}

// The measured response time of one channel, over the deployment's window.
message InboxResponseTime {
  string channel = 1;
  bool measured = 2;
  // config_missing (no window or no minimum set) or too_few_leads.
  repeated string not_measured_codes = 3;
  int32 answered = 4;
  int64 median_seconds = 5;
  int64 p90_seconds = 6;
  // Messages with no first response, older than the account's own threshold
  // when it set one (website_form counts as the Leads > Inbound card does; the
  // other channels count what waits for a person).
  int32 unanswered = 7;
}

message UnifiedInbox {
  repeated InboxRow rows = 1;
  // "" = no further page.
  string next_page_token = 2;
  // How many rows match the filters (all pages).
  int32 total = 3;
  // True when the account holds more records than one read looks at: the
  // oldest are left out, never guessed.
  bool truncated = 4;
  // Counts over the filtered rows.
  repeated InboxCount by_channel = 5;
  repeated InboxCount by_action = 6;
  // The measured response time per channel (website_form, email_inbox,
  // instagram_dm), never filtered by the page's filters.
  repeated InboxResponseTime response_times = 7;
  int32 window_days = 8;
  int32 min_leads = 9;
  // The account's own "unanswered after" threshold in hours (0 = not set).
  int32 threshold_hours = 10;
  // Messages the inbox reader looked at and recorded only as a count (not a
  // pitch, a customer or lead): no record exists to list.
  repeated InboxReadCount counted_only = 11;
  // What the account's switches and mailbox say, from recorded facts.
  InboxReadingState reading = 12;
  bool first_response_enabled = 13;
  bool vendor_pitch_enabled = 14;
}

docs/api-reference/campaigns-and-results.body:
Campaigns and results

The services behind Campaigns (the board, campaign pages, plans,
approvals and Autopilot) and the measured results. Package pulse.v1; the
least role of each method is in its table. See
Autopilot and agencies.
Notes

Measured only. Metrics come from connected sources (Google Analytics,
Google Ads, Google Search Console) and the leads PULSE holds. Published posts
have their own results. A channel with no connector has no rows. A figure is
counted only when measured_fields names it; measured_days of 0 means
nothing was measured.
Forecasts. GetForecast extends the stored Google Analytics series.
season_period_days is 0 when no seasonality was found.
Autopilot queues approved posts at the account's best time through the
same publishing gate as any scheduled post, so the switches on
Switches and arming order
still decide at send time.
Automations do outbound work only when your administrator armed them and
each step's own channel; a dry run never sends.
Campaign plans follow the person's capacity and dates; KPI results come
only from measured post results.


CampaignService
Campaign CRUD, budget tracking, and archiving.
pulse.v1.CampaignService, declared in pulse.proto.



Method
Request → Response
Least role
Notes




CreateCampaign
CreateCampaignRequest → Campaign
editor
CreateCampaign creates a new marketing campaign.


GetCampaign
GetCampaignRequest → Campaign
viewer
GetCampaign returns a campaign by ID.


ListCampaigns
ListCampaignsRequest → ListCampaignsResponse
viewer
ListCampaigns returns paginated campaigns.


UpdateCampaign
UpdateCampaignRequest → Campaign
editor
UpdateCampaign updates campaign details.


DeleteCampaign
DeleteCampaignRequest → google.protobuf.Empty
editor
DeleteCampaign soft-deletes a campaign.


ArchiveCampaign
ArchiveCampaignRequest → Campaign
editor
ArchiveCampaign moves a campaign to archived status.


ListCampaignPlans
ListCampaignPlansRequest → ListCampaignPlansResponse
viewer
ListCampaignPlans lists the caller's campaign plans: the campaigns an audit's content gaps proposed, with their state, newest first.


GetCampaignPlan
GetCampaignPlanRequest → CampaignPlan
viewer
GetCampaignPlan returns one campaign's plan: the gaps it was proposed from, its content strategy and its roadmap, one board per channel.


AcceptCampaignProposal
AcceptCampaignProposalRequest → CampaignPlan
editor
AcceptCampaignProposal accepts a proposed campaign (with the user's edits) and prepares its content strategy and roadmap in the background; GetCampaignPlan reports the progress. Nothing is published.


DismissCampaignProposal
DismissCampaignProposalRequest → CampaignPlan
editor
DismissCampaignProposal dismisses a proposal; the campaign row is kept.


DraftCampaignProposal
DraftCampaignProposalRequest → CampaignPlan
editor
DraftCampaignProposal prepares a proposal's strategy and roadmap in the background WITHOUT accepting it, so its board can be read before the choice; accepting it then keeps that board. Nothing is published.


SetCampaignStatus
SetCampaignStatusRequest → Campaign
editor
SetCampaignStatus starts, pauses or resumes a campaign (ACTIVE or PAUSED only). The daily engines work only on active campaigns; an archived campaign is refused.



Also uses Channel, CampaignStatus, PaginationRequest, PaginationResponse, ContentGapsResponse, ContentStrategyResponse, ContentGap, ContentPillar, GapEvidence.
message SetCampaignStatusRequest {
  string id = 1;
  CampaignStatus status = 2; // CAMPAIGN_STATUS_ACTIVE | CAMPAIGN_STATUS_PAUSED
}

// The state of a campaign plan.
enum CampaignPlanState {
  CAMPAIGN_PLAN_STATE_UNSPECIFIED = 0;
  // Proposed from an audit's content gaps; waiting for the user.
  CAMPAIGN_PLAN_STATE_PROPOSED = 1;
  // Accepted; the strategy and roadmap are being prepared.
  CAMPAIGN_PLAN_STATE_PREPARING = 2;
  // Strategy and roadmap are ready.
  CAMPAIGN_PLAN_STATE_READY = 3;
  // Preparing failed; detail says why. Accepting again retries.
  CAMPAIGN_PLAN_STATE_FAILED = 4;
  CAMPAIGN_PLAN_STATE_DISMISSED = 5;
  // Still a proposal; its strategy and roadmap are being drafted.
  CAMPAIGN_PLAN_STATE_DRAFTING = 6;
}

message ListCampaignPlansRequest {}

message ListCampaignPlansResponse {
  repeated CampaignPlan plans = 1; // summaries: no strategy, gaps or boards
}

message GetCampaignPlanRequest {
  string campaign_id = 1;
}

message AcceptCampaignProposalRequest {
  string campaign_id = 1;
  // The user's edits; empty keeps the proposed value.
  string name = 2;
  string objective = 3;
  string description = 4;
}

message DismissCampaignProposalRequest {
  string campaign_id = 1;
}

message DraftCampaignProposalRequest {
  string campaign_id = 1;
}

message CampaignPlan {
  Campaign campaign = 1;
  CampaignPlanState state = 2;
  // Why the state is what it is: the failure, or the step being prepared.
  string detail = 3;
  // The goal chip of the audit the objective was matched to ("" = none of
  // the audit's goals maps to a campaign objective).
  string goal = 4;
  // Why PULSE proposed this campaign, citing the gaps.
  string rationale = 5;
  string audit_run_id = 6;
  string domain = 7;
  // The gaps the proposal was made from (unset in a list).
  ContentGapsResponse gaps = 8;
  // Unset until the strategy is prepared (and in a list).
  ContentStrategyResponse strategy = 9;
  // One board per channel, in the order of the channels.
  repeated RoadmapBoard boards = 10;
  // Where the boards' channels came from: "settings" (the active channels
  // in Settings) or "campaign" (none set there; the campaign's channels).
  string channels_source = 11;
  // The roadmap run's verdicts, accepted AND withheld.
  runink.ui.judgement.v1.JudgementSet roadmap_judgements = 12;
  google.protobuf.Timestamp updated_at = 13;
  // When the check-up (audit_run_id) this proposal came from ran; unset
  // when it is not known (no run, or the run was removed).
  google.protobuf.Timestamp audit_at = 14;
}

message RoadmapBoard {
  Channel channel = 1;
  repeated RoadmapItem items = 2;
}

// One planned piece of the roadmap and the Studio function that makes it.
message RoadmapItem {
  string id = 1;
  string campaign_id = 2;
  Channel channel = 3;
  int32 week = 4;           // 1-based week of the campaign
  string phase = 5;
  // post | article | whitepaper | podcast | short | presentation |
  // infographic | course | email
  string format = 6;
  string topic = 7;
  string brief = 8;
  // The content gap this item closes ("" = none cited).
  string gap_topic = 9;
  // The Studio tab that makes this format (/studio?tab=…).
  string studio_tab = 10;
  // The content row made for it ("" = not created yet).
  string content_id = 11;
  // That row's place on the board: draft | review | approved | scheduled |
  // published | rejected; "" when there is no row.
  string content_state = 12;
  string content_title = 13;
  runink.ui.judgement.v1.Judgement judgement = 14;
  // Why the reviewer rejected that row (its reviewer notes); set only when
  // content_state is "rejected", "" when no reason was given.
  string content_notes = 15;
}

message Campaign {
  string id = 1;
  string user_id = 2;
  string name = 3;
  string description = 4;
  string objective = 5;       // "brand_awareness", "lead_gen", "engagement", "sales"
  repeated Channel channels = 6;
  CampaignStatus status = 7;
  double budget = 8;
  double spent = 9;
  string currency = 10;       // "BRL", "USD", etc.
  google.protobuf.Timestamp start_date = 11;
  google.protobuf.Timestamp end_date = 12;
  string target_audience = 13;
  map metadata = 14;
  google.protobuf.Timestamp created_at = 15;
  google.protobuf.Timestamp updated_at = 16;
  // Diagnostic this campaign was created from, when set via the diagnostic
  // result page's "Create Campaign" action — empty for campaigns created
  // standalone from the Campaigns screen.
  string diagnostic_id = 17;
  // False while nothing writes a measured spend for this campaign: `spent`
  // is then not a figure and must be shown as not measured, never as 0.
  bool spend_measured = 18;
}

message CreateCampaignRequest {
  string name = 1;
  string description = 2;
  string objective = 3;
  repeated Channel channels = 4;
  double budget = 5;
  string currency = 6;
  google.protobuf.Timestamp start_date = 7;
  google.protobuf.Timestamp end_date = 8;
  string target_audience = 9;
  string diagnostic_id = 10;
}

message GetCampaignRequest {
  string id = 1;
}

message ListCampaignsRequest {
  PaginationRequest pagination = 1;
  CampaignStatus status_filter = 2;
}

message ListCampaignsResponse {
  repeated Campaign campaigns = 1;
  PaginationResponse pagination = 2;
}

message UpdateCampaignRequest {
  string id = 1;
  string name = 2;
  string description = 3;
  string objective = 4;
  repeated Channel channels = 5;
  double budget = 6;
  string currency = 7;
  google.protobuf.Timestamp start_date = 8;
  google.protobuf.Timestamp end_date = 9;
  string target_audience = 10;
}

message DeleteCampaignRequest {
  string id = 1;
}

message ArchiveCampaignRequest {
  string id = 1;
}

ContentPlanService
ContentPlanService — a campaign as a real content plan (owner, 2026-10-29): campaign › phases (dated, around an optional event) › posts (a calendar row each: date, format, topic, persona, hook, call to action, posting time in the account's time zone), a Stories plan per day on Instagram, a tone of voice per persona and three KPIs.
The rules a reader can rely on:  The person states the capacity (posts per week per channel, stories per day) and the dates; PULSE lays the calendar out inside them, keeps the promotional ratio, and posts at the account's MEASURED best time where results exist, otherwise at a starting time it labels as not measured.  Topics, hooks and personas are proposed by the campaign-plan skill; the plan is checked for capacity, ratio, dates and duplicates and reviewed. A plan that fails the review is not saved.  Personas come from the account's audit and leads, never invented.  KPI targets are proposals; KPI results are measurements read from the account's published posts, absent until something was measured. * Nothing here publishes. A post is written in Studio and approved on the Drafts tab; approval hands it to the existing autopilot schedule and publishing checks (publishing must be enabled for the channel).
pulse.v1.ContentPlanService, declared in content_plan.proto.



Method
Request → Response
Least role
Notes




ProposeContentPlan
ProposeContentPlanRequest → ContentPlan
editor
ProposeContentPlan lays out (or lays out again) a campaign's plan from the person's capacity and dates. Posts already written are kept.


GetContentPlan
GetContentPlanRequest → ContentPlan
viewer
GetContentPlan returns a campaign's plan with its KPI results as measured now. NotFound when the campaign has none yet.



Also uses Channel.
// How much the person can do on one channel.
message ChannelCapacity {
  Channel channel = 1;
  // Feed posts a week on this channel (1-14).
  int32 posts_per_week = 2;
}

message ProposeContentPlanRequest {
  string campaign_id = 1;
  // YYYY-MM-DD, the first and last day of the campaign.
  string start_date = 2;
  string end_date = 3;
  // YYYY-MM-DD of the event the campaign is built around; "" = none.
  string event_date = 4;
  // Days the event lasts (1 when unset).
  int32 event_days = 5;
  repeated ChannelCapacity capacity = 6;
  // Instagram Stories per day during the live phase (0 = no Stories plan).
  int32 stories_per_day = 7;
  // One promotional post in every N (e.g. 4 = 1 in 4). 0 = PULSE's default of 4.
  int32 promo_every = 8;
}

message GetContentPlanRequest {
  string campaign_id = 1;
}

// One dated phase of the campaign.
message PlanPhase {
  // build_up | live | follow_up
  string kind = 1;
  string name = 2;
  string start_date = 3;
  string end_date = 4;
  // What this phase is for, in plain words (the model's proposal).
  string goal = 5;
}

// One post on the calendar.
message PlannedPost {
  // The roadmap item it is (Studio's Create/Edit write it).
  string id = 1;
  string campaign_id = 2;
  Channel channel = 3;
  // build_up | live | follow_up
  string phase = 4;
  string date = 5;
  // HH:MM in the account's time zone.
  string time = 6;
  // true = the time is the account's measured best time; false = a starting
  // suggestion, not measured yet.
  bool time_measured = 7;
  // carousel | reel | single_image | short | video | post
  string format = 8;
  string topic = 9;
  string persona = 10;
  string hook = 11;
  string cta = 12;
  bool promo = 13;
  // The written piece, once Studio made it ("" = not written yet), and where
  // it is: draft | review | approved | scheduled | published | rejected.
  string content_id = 14;
  string content_state = 15;
  // Why the reviewer rejected it; only when content_state is "rejected".
  string content_notes = 16;
}

// One Story on an Instagram day.
message PlannedStory {
  string id = 1;
  string date = 2;
  string time = 3;
  string visual = 4;
  string text = 5;
  // poll | quiz | question | link | none
  string sticker = 6;
}

// How the business sounds to one persona.
message PersonaTone {
  string persona = 1;
  repeated string adjectives = 2;
  string example = 3;
}

// One campaign KPI: the target is PULSE's proposal; the result is measured.
message PlanKpi {
  string name = 1;
  // impressions | reactions | comments | engagement | posts_published
  string metric = 2;
  // The proposed target for the whole campaign.
  double target = 3;
  // Measured from the campaign's published posts; absent until measured.
  optional double result = 4;
  // Posts the result was measured from.
  int32 measured_posts = 5;
}

// One deterministic check on the plan.
message PlanCheck {
  string id = 1;
  bool pass = 2;
  repeated string findings = 3;
}

message ContentPlan {
  string campaign_id = 1;
  string start_date = 2;
  string end_date = 3;
  string event_date = 4;
  int32 event_days = 5;
  repeated ChannelCapacity capacity = 6;
  int32 stories_per_day = 7;
  int32 promo_every = 8;
  // The account's time zone as minutes east of UTC.
  int32 utc_offset_minutes = 9;
  repeated PlanPhase phases = 10;
  repeated PlannedPost posts = 11;
  repeated PlannedStory stories = 12;
  repeated PersonaTone tone = 13;
  repeated PlanKpi kpis = 14;
  repeated PlanCheck checks = 15;
  // concur | unable | off: the review verdict on the plan.
  string verdict = 16;
  string verdict_reason = 17;
  // Plain notes: what PULSE could not do or measure.
  repeated string notes = 18;
  string updated_at = 19;
}

EpicService
