  // Drafts now approved or published whose last change falls in the range.
  int64 drafts_approved = 2;
  // Leads Find Leads or an audit saved in the range.
  int64 leads_found = 3;
  // Leads now past "new" (contacted, qualified, won or lost): today's
  // count, not the range's.
  int64 leads_moved_on = 4;
  // Outreach drafts (email, call script, LinkedIn message) written in the range.
  int64 outreach_drafts = 5;
  // Follow-up tasks marked done in the range.
  int64 tasks_done = 6;
  // Drafts waiting for review now.
  int64 awaiting_review = 7;
}

message GetMetricsSummaryRequest {
  DateRange date_range = 1;
  string campaign_id = 2; // optional filter
}

message MetricsSummary {
  int64 total_followers = 1;
  int64 total_impressions = 2;
  int64 total_engagements = 3;
  double engagement_rate = 4;
  int64 total_clicks = 5;
  int64 total_leads = 6;
  double conversion_rate = 7;
  int64 content_published = 8;
  double follower_growth_rate = 9;
  double reach = 10;
  map channel_scores = 11; // per-channel health score 0-100
  // Days with any recorded metric in the range. 0 = nothing was measured,
  // so the totals above are not measurements and must not be shown as 0.
  int32 measured_days = 12;
  // Google Ads cost in micros of spend_currency; conversions as Ads reports
  // them. Each counts only when measured_fields names it ("spend",
  // "conversions").
  int64 total_spend_micros = 13;
  double total_conversions = 14;
  string spend_currency = 15;
  // The totals measured on at least one day in the range: "followers",
  // "impressions", "engagements", "clicks", "leads", "spend", "conversions".
  // A total not listed is not measured, whatever its value.
  repeated string measured_fields = 16;
}

message GetDailyEvolutionRequest {
  DateRange date_range = 1;
  repeated Channel channels = 2;
  string metric_type = 3; // "followers", "engagement", "impressions", "leads"
}

message DailyEvolutionResponse {
  repeated MetricPoint data_points = 1;
  // Per-channel slope of the daily series; only channels with enough days to
  // test it appear (see trends for the others).
  map trend_slopes = 2;
  // Per-channel trend with what supports it. A channel with too few days is
  // here with measured=false, never as a zero slope.
  map trends = 3;
}

// ChannelTrend is the trend of one channel's daily series and the evidence for
// its direction.
message ChannelTrend {
  // false: too few days to say anything; only points is set.
  bool measured = 1;
  // Days the trend was computed over.
  int32 points = 2;
  // Change per day.
  double slope = 3;
  double std_err = 4;
  // Absent when the fit is exact (no spread to test against).
  optional double t = 5;
  // Two-sided p-value of the slope against zero.
  double p = 6;
  // "rising" or "falling" only when the slope is supported by the test;
  // "flat" means no direction is supported (not that nothing changed).
  string direction = 7;
  // Days a channel needs before its trend can be tested.
  int32 min_points = 8;
}

message GetChannelDistributionRequest {
  DateRange date_range = 1;
}

message ChannelDistribution {
  Channel channel = 1;
  double percentage = 2;
  int64 absolute_value = 3;
  // Percent change against the equal-length window just before. Absent (not
  // zero) when that window has no measured engagement for the channel: there is
  // nothing to compare with.
  optional double growth_rate = 4;
  // The stored channel ("web", "google_ads", "crm" …), which the Channel enum
  // cannot name.
  string channel_name = 5;
}

message ChannelDistributionResponse {
  repeated ChannelDistribution distributions = 1;
}

message GetAgentReadingRequest {
  DateRange date_range = 1;
  string focus_area = 2; // "growth", "engagement", "content_performance", "overall"
}

message AgentReadingResponse {
  string summary = 1;
  repeated string key_insights = 2;
  repeated string recommendations = 3;
  double confidence = 4;
  google.protobuf.Timestamp generated_at = 5;
  // True when nothing was measured in the range: no model was asked.
  bool not_measured = 6;
}

AnalyticsService
Google Analytics (GA4) trend data and forecasting. SyncGaData pulls a metric's daily time series from the configured GA4 property (see IntegrationService for how the service-account credential is stored) into a local cache. GetTrends reads that cache. GetForecast forecasts from the cached series, with no live GA call, so it is fast and works even if GA is temporarily unreachable.
