Method
Request → Response
Least role
Notes




SyncGaData
SyncGaDataRequest → SyncGaDataResponse
editor
SyncGaData pulls the latest daily metric values from GA4 into the local cache.


GetTrends
GetTrendsRequest → GetTrendsResponse
viewer
GetTrends returns the cached historical daily time series for a metric.


GetForecast
GetForecastRequest → GetForecastResponse
viewer
GetForecast forecasts a metric from the cached time series.



Also uses MetricPoint.
message SyncGaDataRequest {
  string metric = 1;    // GA4 metric API name, e.g. "sessions", "activeUsers", "conversions"
  int32 lookback_days = 2; // defaults to 90 if unset
}

message SyncGaDataResponse {
  int32 synced_count = 1;
  google.protobuf.Timestamp synced_at = 2;
}

message GetTrendsRequest {
  string metric = 1;
  int32 days = 2; // defaults to 90 if unset
}

message GetTrendsResponse {
  repeated MetricPoint points = 1;
  string metric = 2;
  // False when the caller has no Google Analytics connection: no points is
  // then "not connected", an answer, not an error.
  bool ga_connected = 3;
}

message GetForecastRequest {
  string metric = 1;
  int32 horizon_days = 2; // number of future days to forecast, defaults to 14
}

message GetForecastResponse {
  repeated MetricPoint historical = 1;
  repeated ForecastPoint forecast = 2;
  repeated string anomalies = 3;    // human-readable notes on historical anomalies
  repeated google.protobuf.Timestamp changepoints = 4; // dates where the trend slope shifted
  int32 season_period_days = 5;     // 0 = no seasonality detected
  // False when the caller has no Google Analytics connection.
  bool ga_connected = 6;
  // True when there are too few synced days to forecast: historical is set,
  // forecast is empty. An answer, not an error.
  bool too_few_days = 7;
  // true: the days were enough to check for unusual points, so an empty
  // anomalies list means none were found. false: not enough days to check;
  // anomalies is empty because nothing was checked.
  bool anomalies_checked = 8;
  // Days a series needs before it can be checked for unusual points.
  int32 anomaly_min_days = 9;
  // How the forecast was made; unset when there is no forecast.
  ForecastModel model = 10;
  // Why there is no forecast although there were enough days ("no_model":
  // no model could be fitted to the series). Empty otherwise.
  string forecast_unavailable = 11;
}

// ForecastModel says which model made the forecast and why, as a code and
// the figures behind it.
message ForecastModel {
  // The model used.
  string name = 1;
  // Its settings, e.g. the order or the season length.
  string spec = 2;
  // backtest_won | backtest_tie | no_holdout | single_model.
  string why_code = 3;
  // Days held out of the fit to compare models; 0 when none.
  int32 holdout_days = 4;
  // Mean absolute error on the held-out days of the model used and of the
  // other one; absent when that model was not evaluated.
  optional double chosen_error = 5;
  optional double other_error = 6;
  string other_name = 7;
  // Share of the interval, e.g. 0.95.
  double interval_level = 8;
  // Synced days of history the model was fitted on.
  int32 history_points = 9;
  // True when history_points is below the floor at which the interval can be
  // trusted to hold its share (60 days): the range is shown, marked approximate.
  bool interval_approximate = 10;
  // The history floor interval_approximate is judged against (the card names it).
  int32 interval_min_points = 11;
}

// ForecastPoint is one future predicted value. Bounds are the interval the
// model gives for that day; it widens the further out the day is.
message ForecastPoint {
  google.protobuf.Timestamp date = 1;
  double predicted_value = 2;
  double lower_bound = 3;
  double upper_bound = 4;
}

GrowthPlanService
GrowthPlanService — the 90-day plan (owner, 2026-11-06: "qualified inbound leads and roadmap automation plans, road map and action plans for 90 days"). The spine of the console: made from the latest check-up, three 30-day phases (fix and foundations, publish and attract, convert and scale), weekly actions.
The rules a reader can rely on:  Every action comes from one finding of the check-up (a site-score fix, an AI-access failure, a buyer question the AI answers without the business, a missing Discover or retention item, a content gap's campaign item, a lead the check-up found). An action without its finding is never made.  The plan is laid out from what was measured.  Editing (accept, drop, move, owner) changes only the plan. Nothing the plan links to is created by the plan: a piece is still written and approved on the board, an email still waits for its send, a fix still goes through the site report.  KPIs are computed when read, from measured baselines only. A KPI with no source reads "not measured", with the step that would measure it.
