}

message SaveGrowthReviewRequest {
  int32 week = 1;
  string wins = 2;
  string challenges = 3;
  string notes = 4;
  optional int32 satisfaction = 5; // 1..10
}

// One public benchmark a reasoned value rests on.
message BenchmarkSource {
  string url = 1;
  string title = 2;
  string quote = 3;           // the words the figure was read from
  double figure = 4;
  google.protobuf.Timestamp read_at = 5;
  string query = 6;           // the search that found it
}

// One step of the reasoning, with how sure it is.
message ReasonStep {
  string text = 1;
  string confidence = 2;      // high | medium | low
}

// A value PULSE reasoned for this business: never a bare number. It carries
// its sources, or assumed=true ("assumed, no benchmark found") with low
// confidence.
message GrowthReasoned {
  // Which value this is (a stable identifier).
  string key = 1;
  double value = 2;
  string unit = 3;            // percent | points | touches | days
  string confidence = 4;      // high | medium | low
  repeated ReasonStep steps = 5;
  repeated BenchmarkSource sources = 6;
  bool assumed = 7;
  google.protobuf.Timestamp set_at = 8;
  string by = 9;              // who set it
  bool overridden = 10;
  double override_value = 11;
  google.protobuf.Timestamp overridden_at = 12;
  double effective = 13;      // the override when set, else value
  string scenario = 14;       // the business scenario it was reasoned for
}

// One week's review (the check-ins of the retired 30-day cycle move here).
message GrowthReview {
  int32 week = 1;
  string wins = 2;
  string challenges = 3;
  string notes = 4;
  bool rated = 5;             // false: no satisfaction given
  int32 rating = 6;           // satisfaction 1..10
  google.protobuf.Timestamp created_at = 7;
  bool from_check_in = 8;     // migrated from a 30-day-cycle check-in
  int64 posts_published = 9;
  int64 leads = 10;
}

message GetGrowthPlanRequest {}

message MakeGrowthPlanRequest {}

message UpdateGrowthActionRequest {
  string action_id = 1;
  // proposed | accepted | done | dropped; unset = unchanged.
  optional string status = 2;
  // 1..13; unset = unchanged.
  optional int32 week = 3;
  // "you", "pulse", or a name; unset = unchanged.
  optional string owner = 4;
}

message GrowthPlan {
  // false: no plan yet. latest_run_id says whether one can be made.
  bool exists = 1;
  string id = 2;
  string audit_run_id = 3;
  string domain = 4;
  google.protobuf.Timestamp checkup_at = 5;
  google.protobuf.Timestamp start_date = 6;
  // The week of the 90 days today falls in: 1..13; 0 before the start,
  // 14 after the end.
  int32 current_week = 7;
  repeated GrowthPhase phases = 8;
  repeated GrowthWeek weeks = 9;
  repeated GrowthAction actions = 10;
  // The caller's latest full check-up ("" = none: run one first).
  string latest_run_id = 11;
  google.protobuf.Timestamp latest_checkup_at = 12;
  // True when latest_run_id is newer than the plan's check-up.
  bool newer_checkup = 13;
  // What PULSE reasoned for this business, and the state of that reasoning:
  // "" never ran | running | done | kept (it could not run now:
  // the last values are kept, reasoning_note says why and since when)
  // | failed.
  repeated GrowthReasoned reasoned = 14;
  string reasoning_state = 15;
  string reasoning_note = 16;
  google.protobuf.Timestamp reasoned_at = 17;
  repeated GrowthReview reviews = 18;
  // What the plan's caps left out of the check-up, one entry per kind that
  // was cut. Empty = nothing was cut OR the plan was made before this field
  // existed (the page cannot tell those apart, so it says nothing either way).
  repeated GrowthCut cuts = 19;
}

// GrowthCut is one cap that left findings out of the plan: the check-up found
// more of this kind than the plan carries.
message GrowthCut {
  // The kind of finding (a stable identifier).
  string source = 1;
  // The most the plan carries of this kind.
  int32 cap = 2;
  // How many findings of this kind the check-up had beyond the cap.
  int32 not_planned = 3;
}

message GrowthPhase {
  int32 number = 1;    // 1, 2, 3
  string key = 2;      // fix | attract | convert
  int32 first_week = 3;
  int32 last_week = 4;
  google.protobuf.Timestamp starts = 5;
  google.protobuf.Timestamp ends = 6;
  int32 total = 7;     // actions not dropped
  int32 done = 8;
  repeated GrowthKpi kpis = 9;
}

message GrowthWeek {
  int32 week = 1;
  google.protobuf.Timestamp starts = 2;
  int32 total = 3;     // actions not dropped
  int32 done = 4;
}

// One KPI. Every figure is measured or absent; absent is never 0.
message GrowthKpi {
  // Which figure this is (a stable identifier).
  string key = 1;
  bool measured = 2;          // false: no baseline; why_not and connect say why
  double baseline = 3;
  // What the baseline was measured from (a stable identifier).
  string baseline_basis = 4;
  bool has_target = 5;
  double target_value = 6;
  // What the target is based on (a stable identifier).
  string target_basis = 7;
  bool has_current = 8;
  double current_value = 9;
  // What the current value is measured from (a stable identifier).
  string current_basis = 10;
  // Set when measured is false: a stable code for why it is not measured.
  string why_not = 11;
  string connect_route = 12;  // the in-app page that would measure it
  // The reasoned value the target follows from ("" = none: the target
  // follows from the plan's own actions or the check-up).
  string reasoned_key = 13;
}

message GrowthAction {
  string id = 1;
  int32 phase = 2;
  int32 week = 3;
  // The kind of action (a stable identifier).
  string kind = 4;
  // What to do, in the finding's own words (a check's title, a question,
  // a topic, a lead's name); the page puts the kind's verb before it.
  string what = 5;
  // Why: the finding's own evidence (a check's rationale and severity, a
  // gap's rationale and opportunity, what the AI answer cited). Never empty.
  string why = 6;
  // The kind of finding the action came from (a stable identifier).
  string source_kind = 7;
  string source_ref = 8;
  string source_url = 9;
  string owner = 10;          // you | pulse | a name
  string status = 11;         // proposed | accepted | done | dropped
  // Done because the data shows it (published, contacted, the check passed
  // at a later check-up), with how; false = the person's own tick or not done.
  bool done_measured = 12;
  string done_basis = 13;
  GrowthAutomation automation = 14;
  // What kind of item it drives.
  string target_kind = 15;
  string target_id = 16;
  string link = 17;           // in-app route that opens it
  bool edited_by_hand = 18;
}

// The automation an action runs on: the existing per-target automations
// (AutomationService.GetTargetAutomation) or the site report's ready fix.
message GrowthAutomation {
  // The kind of automation (a stable identifier; "none" when there is none).
  string kind = 1;
  string target_kind = 2;     // lead | campaign_item | "" (none)
  string target_id = 3;
}

docs/api-reference/content/.body:
Studio and content

The services behind Studio (formats, skills, the library) and the content
records that Campaigns show and publish. Package pulse.v1; the least role of
each method is in its table. See Studio.
Notes

Our own models only. Everything here generates on the platform's own
models. Still images are ImageService's: only a person asks for one, each is an
"AI-generated" draft until a person approves it, and GenerateCreative for a still
image answers FailedPrecondition and points there.
Skills. Each content type is a skill with its own checks; drafts pass
PULSE's safety rules and the plan gate, and land on the board with their
scores in content.metadata.
Publishing queue. status is pending, publishing, posted,
withheld or failed. reason_status is recorded, none, missing or
unavailable: never read an empty reason as "nothing to report" without
checking it.
Speech comes from the platform's speech service. When it is off, a
method that needs speech answers Unavailable rather than silence.


