editor
GenerateCreative generates a creative (a document or a podcast) from a prompt and persists it as a Creative, unlike CreateCreative, which only registers metadata for an already-uploaded asset. A still image is not available and returns Unimplemented.


AttachContentMedia
AttachContentMediaRequest → AttachContentMediaResponse
editor
AttachContentMedia attaches the caller's own uploaded photo or video (an AuditAttachmentService upload) to a piece as a creative, stored encrypted so Instagram can publish it as a post, Reel or Story. On an Instagram piece the file is checked against Instagram's documented rules first (FAILED_PRECONDITION with the reason in plain words).


DownloadContent
DownloadContentRequest → DownloadContentResponse
viewer
DownloadContent makes the caller's piece into files the person can post themselves, with or without a connected account: Instagram = the image(s) and caption.txt (caption, hashtags, alt text) in one .zip; a text channel = its text file. Missing assets are made on demand (an Instagram post's image). Nothing is published.


GetPublishOutcome
GetPublishOutcomeRequest → PublishOutcome
viewer
GetPublishOutcome says where the caller's approved piece stands on its channel: published, scheduled, sending, or withheld with the content ready to download (DownloadContent). Read-only; another user's piece is NotFound.


UpdateInstagramMentions
UpdateInstagramMentionsRequest → UpdateInstagramMentionsResponse
editor
UpdateInstagramMentions reads, adds or removes the accounts an Instagram piece mentions. A handle comes from what PULSE has on record (partners, leads, competitors when asked) or from the person; each added one is looked up with Instagram business discovery, and only a found one is tagged when the piece is posted. Nothing is published.



Also uses StreamChunk, Channel, AssistantToolEvent, AssistantProposal, PaginationRequest, ContentStatus, PaginationResponse.
message GenerateContentRequest {
  Channel channel = 1;
  string topic = 2;
  string tone = 3;            // "professional", "casual", "bold", "educational"
  string target_audience = 4;
  string campaign_id = 5;     // optional - link to campaign
  string diagnostic_id = 6;   // optional - use diagnostic context
  string additional_context = 7;
  string language = 8;        // e.g. "pt-BR"
  // The strategy-roadmap item this piece is made for (CampaignService
  // GetCampaignPlan): the stored row is linked to it, so its status shows on
  // the roadmap card. Optional.
  string roadmap_item_id = 9;
}

message Content {
  string id = 1;
  string user_id = 2;
  Channel channel = 3;
  string title = 4;
  string body = 5;
  string hashtags = 6;
  string call_to_action = 7;
  ContentStatus status = 8;
  string campaign_id = 9;
  string tone = 10;
  string language = 11;
  string reviewer_notes = 12;
  map metadata = 13;
  google.protobuf.Timestamp created_at = 14;
  google.protobuf.Timestamp updated_at = 15;
  google.protobuf.Timestamp published_at = 16;
  // Diagnostic this content was generated from, when GenerateContentRequest
  // set diagnostic_id — empty if generated without diagnostic context.
  string diagnostic_id = 17;
  // What the row is as stored ("campaign_brief", "social_post", a channel
  // name, ...): the channel enum cannot say that a row is not a post.
  string format = 18;
  // True when the body is only the brief it was planned from (an audit
  // suggestion's one line): nothing was written yet, so it cannot be
  // approved or scheduled until it is written.
  bool not_written = 19;
  // How the approval ended (ApproveContent only; unset on every other read).
  PublishOutcome publish_outcome = 20;
}

message ListContentRequest {
  PaginationRequest pagination = 1;
  ContentStatus status_filter = 2;
  Channel channel_filter = 3;
  string campaign_id = 4;
}

message ListContentResponse {
  repeated Content content = 1;
  PaginationResponse pagination = 2;
}

message UpdateContentRequest {
  string content_id = 1;
  string title = 2;
  string body = 3;
  string hashtags = 4;
  string call_to_action = 5;
}

message ApproveContentRequest {
  string content_id = 1;
  string reviewer_notes = 2;
}

message SaveGeneratedContentRequest {
  string title = 1;
  string body = 2;
  Channel channel = 3;      // optional; a sensible default is applied server-side
  string campaign_id = 4;   // optional
  string diagnostic_id = 5; // optional
  // The strategy-roadmap item this piece is made for; see
  // GenerateContentRequest.roadmap_item_id. Optional.
  string roadmap_item_id = 6;
  // The Studio format it was made as (a StudioFormat id, "whitepaper");
  // kept in the row's metadata as "studio_format" so the library files it
  // under what it is. Optional.
  string format = 7;
}

