  string reviewer_notes = 2;
  string rejection_reason = 3;
}

// Creative is a visual/media asset associated with content.
message Creative {
  string id = 1;
  string content_id = 2;
  string campaign_id = 3;
  string type = 4;          // "image", "video", "carousel", "story"
  string prompt = 5;        // AI generation prompt
  string url = 6;           // asset URL after generation/upload
  string alt_text = 7;
