  string id = 1;
}

message GenerateCreativeRequest {
  string prompt = 1;
  string content_id = 2;   // optional
  string campaign_id = 3;  // optional
  int32 width = 4;         // not used: a still image or a video is not made from a prompt
  int32 height = 5;        // not used: a still image or a video is not made from a prompt
  int32 duration = 6;      // not used: a video is made from a piece's script (ShortVideoService)
  // The kind of creative: a document format or "podcast". A still image or a
  // video is not made from a prompt (Unimplemented); a short video is made
  // from a piece's script by ShortVideoService.
  string format = 7;
  // Not used.
  int32 scene_count = 8;
  // Not used.
  int32 fps = 9;
  string avatar_id = 10;   // not used: a course module carries no generated video
  string voice_id = 11;
    string template_id = 12;
  string diagnostic_id = 13;
  string target_language = 14; // English, French, Spanish, Portuguese, etc.
}

