// PublishOutcomeKind is how an approval or a send ended. Publishing is never
// a dead end (owner, 2026-11-20): it ends published, on its way, or with the
// content ready to download.
enum PublishOutcomeKind {
  PUBLISH_OUTCOME_KIND_UNSPECIFIED = 0; // not approved, or nothing recorded
  PUBLISH_OUTCOME_PUBLISHED = 1;        // sent to the channel
  PUBLISH_OUTCOME_SCHEDULED = 2;        // queued: the publishing worker sends it at its time
  PUBLISH_OUTCOME_SENDING = 3;          // in flight right now
  // Not sent (publishing is off, no account, or the send failed): nothing was
  // lost and the piece can be downloaded with DownloadContent.
  PUBLISH_OUTCOME_DOWNLOAD_READY = 4;
}

// PublishReason is why a piece was not sent, for DOWNLOAD_READY.
enum PublishReason {
  PUBLISH_REASON_UNSPECIFIED = 0;
  PUBLISH_REASON_KILL_SWITCH = 1;       // the global publishing switch is off
  PUBLISH_REASON_CHANNEL_DISARMED = 2;  // this channel's own switch is off
  PUBLISH_REASON_NOT_ALLOWLISTED = 3;   // the owner may not publish on this deployment-wide channel
  PUBLISH_REASON_CHANNEL_OFF = 4;       // the owner switched the channel off in Settings
  PUBLISH_REASON_NOT_CONNECTED = 5;     // no account or token for the channel
  PUBLISH_REASON_NO_PUBLISHER = 6;      // PULSE has no way to send to this channel
  PUBLISH_REASON_WAITING_FOR_MEDIA = 7; // the piece lacks a photo or video the platform needs
  PUBLISH_REASON_SEND_FAILED = 8;       // the platform refused or the send failed
  PUBLISH_REASON_OTHER = 9;
}

message PublishOutcome {
  PublishOutcomeKind kind = 1;
  PublishReason reason = 2;       // set when kind is DOWNLOAD_READY
  string reason_text = 3;         // the recorded explanation, plain words
  string published_url = 4;       // set when kind is PUBLISHED and the platform gave a link
  google.protobuf.Timestamp scheduled_at = 5; // set when kind is SCHEDULED, if known
  // True when kind is DOWNLOAD_READY: call DownloadContent for the files.
  bool download_ready = 6;
  // Set when My rules withheld the piece: the id of the check, which the
  // conscience trace (ConscienceTraceService.GetActionTrace) answers with what
  // was checked. Empty for every other outcome.
  string action_id = 7;
}

message GetPublishOutcomeRequest {
  string content_id = 1;
}

