// What the person agreed to, recorded when media is added.
message ConsentRecord {
  // The version of the consent text the person was shown (see
  // ListTwinsResponse.consent_text_version). An unknown version is refused.
  string text_version = 1;
  // The statement the person said or confirmed, as text (at least 10
  // characters).
  string statement_transcript = 2;
  // When the person recorded it, RFC 3339 (not in the future, not older than
  // 24 hours).
  string recorded_at = 3;
  // Set by the server on read: when PULSE accepted it, and when it was
  // withdrawn ("" = not withdrawn).
  string accepted_at = 4;
  string revoked_at = 5;
}

message Twin {
  string id = 1;
  string name = 2;
  // "Course instructor", "Product presenter"...
  string role = 3;
  // "en", "es", "fr" or "pt".
  string language = 4;
  bool built_in = 5;
  // The voice: a built-in voice id or the id of the caller's own.
  string voice_id = 6;
  bool voice_custom = 7;
  // False when the voice cannot be used now, with the reason in voice_note
  // (speech unavailable, no voice for the language, custom voices not
  // available, consent withdrawn).
  bool voice_available = 8;
  string voice_note = 9;
  string voice_licence = 10;
  string voice_attribution = 11;
  // "initials" (a flat colour and the initials), "photo" or "video".
  string appearance_kind = 12;
  string appearance_id = 13;
  string avatar_initials = 14;
  // "#RRGGBB".
  string avatar_colour = 15;
  // True when the twin's consent was withdrawn: it cannot speak.
  bool consent_revoked = 16;
  string created_at = 17;
  // The consents behind the twin's own media (none for a built-in persona).
  repeated ConsentRecord consents = 18;
  // The face shown for a built-in persona (empty for own-appearance twins:
  // they use the photo).
  AvatarStyle avatar = 19;
  // The voice by name (never the raw id), e.g. "Heart".
  string voice_name = 20;
  // True for a built-in voice; false for the caller's own voice.
  bool voice_realtime = 21;
  // A signed, expiring, owner-checked media URL of a small JPEG of the photo
  // (own-appearance twins only; empty for built-ins).
  string thumbnail_url = 22;
  // Set only on the reply to SetTwinConsentRevoked: whether the withdrawn recording is erased or still being erased.
