  // and speakers; it does not change how fast a voice speaks.
  string pace = 6;
  // The Studio piece (the caller's own) this audio belongs to; empty = none.
  string content_id = 7;
}

message VoiceoverEvent {
  // checking, queued (waiting for a free speech slot), speaking, saving or done.
  string phase = 1;
  int32 parts_done = 2;
  int32 parts_total = 3;
  // Set when phase is done.
  Voiceover voiceover = 4;
  // The job this stream is attached to (VoiceoverJob.id).
  string job_id = 5;
}

message Voiceover {
  string id = 1;
  string title = 2;
  // The Studio piece it belongs to; empty = none.
  string content_id = 3;
  // A signed, expiring URL of the audio.
  string url = 4;
  // "wav".
  string format = 5;
  double seconds = 6;
  int64 size_bytes = 7;
  string language = 8;
  string voice_id = 9;
  string second_voice_id = 10;
  string pace = 11;
  int32 speakers = 12;
  int32 parts = 13;
  // Always "AI-generated voice": the audio is synthetic.
  string label = 14;
  bool ai_generated = 15;
  google.protobuf.Timestamp created_at = 16;
}

message VoiceoverLimits {
  int32 max_script_chars = 1;
  int32 max_speakers = 2;
  // Voice-overs the caller can still make today, and the daily limit.
  int32 daily_limit = 3;
  int32 daily_remaining = 4;
  int32 max_title_chars = 5;
}

message ListVoiceoversRequest {
  // Only the voice-overs of this Studio piece; empty = all of the caller's.
  string content_id = 1;
}

message ListVoiceoversResponse {
  repeated Voiceover voiceovers = 1;
  VoiceoverLimits limits = 2;
  // "ok", or why speech is not available ("unavailable: ...").
  string speech_status = 3;
}

message DeleteVoiceoverRequest {
  string id = 1;
}

message DeleteVoiceoverResponse {}

// A voice-over job: the work behind MakeVoiceover, kept on the server. The
// script text is never part of it (it is stored sealed and used only to make the
// audio).
message VoiceoverJob {
  string id = 1;
  // queued (waiting for a free speech slot), making, ready, failed, interrupted
  // (the server restarted while it was being made) or stopped (by the person).
  string state = 2;
  // For failed and interrupted: speech_unavailable, too_long,
  // storage_failed, interrupted, timed_out or internal; a speech service failure
  // carries its own voice_* code (voice_unreachable, voice_failed, ...).
  string reason_code = 3;
  // Parts spoken so far, and the total (0 until the script is split).
  int32 parts_done = 4;
  int32 parts_total = 5;
  // The part that could not be spoken, for reason voice_failed.
  int32 failed_part = 6;
  string title = 7;
  string content_id = 8;
  string language = 9;
  string voice_id = 10;
  string second_voice_id = 11;
  string pace = 12;
  google.protobuf.Timestamp created_at = 13;
  google.protobuf.Timestamp updated_at = 14;
  // Set when state is ready: the saved voice-over.
  Voiceover voiceover = 15;
}

message GetVoiceoverJobRequest {
  string id = 1;
}

message ListVoiceoverJobsRequest {}

message ListVoiceoverJobsResponse {
  repeated VoiceoverJob jobs = 1;
  // Voice-overs made at once on the whole server, and how many of the caller's
  // account at once (always 1).
  int32 max_parallel = 2;
  int32 max_per_account = 3;
  // "ok", or why speech is not available ("unavailable: ...").
  string speech_status = 4;
}

message StopVoiceoverJobRequest {
  string id = 1;
}

message RetryVoiceoverJobRequest {
  string id = 1;
}

PieceAudioService
The state of the spoken audio of a written piece (owner, 2026-11-26: "the application still does not create any video nor audio contents"). A script piece a person asks for in Studio gets its audio with its video, made in the background as a voice-over (VoiceoverService lists and plays it). This says what happened to it, so the piece never shows an empty area: none, making, ready, or failed with a reason CODE (never a URL or a secret) the app says in words. Per account only.
