Discard one image and delete its file (editor or administrator, a person only).



message GetImageStatusRequest {}

message ImageStatus {
  // The server's switch is on and the image service is set up.
  bool available = 1;
  // Why it is not available, as a fixed code (not_configured, switched_off); empty when it is.
  string unavailable_code = 2;
  // The account turned image creation on. Default false.
  bool enabled = 3;
  // Pictures this account may still ask for today.
  int32 remaining_today = 4;
  // The most pictures one request may ask for.
  int32 max_per_request = 5;
  // The aspect presets: square, portrait, landscape, story.
  repeated string aspects = 6;
  // The style presets (codes), each tied to the account's brand colours.
  repeated string styles = 7;
  // The brand colours the pictures are made around, in words; empty = neutral tones.
  repeated string palette = 8;
  // The request text limit, in characters.
  int32 max_request_chars = 9;
}

message SetImageSettingsRequest {
  bool enabled = 1;
}

message GenerateImageRequest {
  // The piece the pictures are for (optional; empty = a standalone picture).
  string content_id = 1;
  string campaign_id = 2;
  // What the picture shows, in your own words.
  string prompt = 3;
  // square | portrait | landscape | story. Default square.
  string aspect = 4;
  // One of the style codes from GetImageStatus. Default brand_flat.
  string style = 5;
  // 1 to 4. Default 1.
  int32 count = 6;
}

message GetImageJobRequest {
  string id = 1;
}

message ImageJob {
  string id = 1;
  // queued | running | done | failed | refused
  string state = 2;
  // Why it did not come out, as a fixed code; empty otherwise.
  string reason_code = 3;
  string aspect = 4;
  string style = 5;
  int32 count = 6;
  // The images that came out so far.
  repeated GeneratedImage images = 7;
  // How many were refused or failed.
  int32 refused = 8;
  int32 failed = 9;
  string content_id = 10;
  // The description it was asked with (empty when it was refused).
  string prompt = 11;
  google.protobuf.Timestamp created_at = 12;
  google.protobuf.Timestamp updated_at = 13;
}

message ListGeneratedImagesRequest {
  // Only the images of this piece (empty = all of the account's).
  string content_id = 1;
  int32 page_size = 2;
}

message ListGeneratedImagesResponse {
  repeated GeneratedImage images = 1;
}

message GeneratedImage {
  string id = 1;
  string content_id = 2;
  // draft | approved
  string status = 3;
  // Always true: every image is labelled as AI-generated.
  bool ai_generated = 4;
  // A short-lived link to the image and to its small preview.
  string url = 5;
  string thumbnail_url = 6;
  int32 width = 7;
  int32 height = 8;
  string aspect = 9;
  string style = 10;
  string alt_text = 11;
  string prompt = 12;
  string job_id = 13;
  google.protobuf.Timestamp created_at = 14;
}

message ApproveGeneratedImageRequest {
  string id = 1;
}

message DiscardGeneratedImageRequest {
  string id = 1;
}

message DiscardGeneratedImageResponse {}

OwnVoiceService
USE MY OWN VOICE in the Voice-over studio (owner, 2026-11-28). OFF by default, three times: the server's switch PULSE_OWN_VOICE, the account's own switch (Settings), and the speech service itself having custom voices on. The voice is only ever the caller's OWN consented recording from the twin flow (DigitalTwinService.AddVoiceSample); no other person's voice is accepted anywhere. Every use is confirmed by the person ("This voice is yours. You confirm you are the speaker."). The audio is synthetic and says so.
pulse.v1.OwnVoiceService, declared in ownvoice.proto.



Method
Request → Response
Least role
Notes




GetOwnVoiceStatus
GetOwnVoiceStatusRequest → OwnVoiceStatus
viewer
Whether "My voice" can be used now, and if not, why (a closed code); the account's switch; the caller's own consented samples; the limits.


SetOwnVoice
SetOwnVoiceRequest → OwnVoiceStatus
editor
Turns the account's own-voice switch on or off (a person only).


MakeOwnVoiceover
MakeOwnVoiceoverRequest → stream VoiceoverEvent
editor
Speaks a script in the caller's own voice (a person only), optionally with a built-in voice for a second speaker, and saves the AI-labelled audio in the caller's library. The speech service learns the voice for this one job and forgets it when the job ends, whatever the outcome.



Also uses VoiceoverEvent, Voiceover.
message GetOwnVoiceStatusRequest {}

message OwnVoiceSample {
  // The twin voice asset (DigitalTwinService) the recording is stored as.
  string id = 1;
  string name = 2;
  // en, fr, es or pt: the language it was recorded in.
  string language = 3;
}

message OwnVoiceStatus {
  // True only when the voice can be used now.
  bool available = 1;
  // The account's own switch (default off).
  bool switch_on = 2;
  // "available", or why not: server_off (the operator's switch), not_on_this_server
  // (the speech service has custom voices off), speech_unreachable, switch_off (the
  // account's switch), no_sample (no consented recording of the caller's own voice).
  string state = 3;
  // The caller's own consented recordings that can be used (not withdrawn).
  repeated OwnVoiceSample samples = 4;
  // At most this many characters in an own-voice script.
  int32 max_script_chars = 5;
  // Own-voice voice-overs a day (PULSE_OWN_VOICE_DAILY_CAP) and how many are left today
  // (the lower of this and the shared voice-over limit).
  int32 daily_cap = 6;
  int32 daily_remaining = 7;
  // The version of the confirmation wording the screen shows with each use.
  string confirmation_version = 8;
}

message SetOwnVoiceRequest {
  bool enabled = 1;
}

message MakeOwnVoiceoverRequest {
  // The words to speak, at most max_script_chars characters. A script with speaker
  // labels ("Host:", "Guest:") speaks the first speaker in the caller's voice and
  // the second in second_voice_id.
  string script = 1;
  string title = 2;
  // The recording to use (OwnVoiceSample.id); empty = the most recent usable one.
  string sample_id = 3;
  // A built-in voice for the second speaker; empty = the caller's own voice too.
  string second_voice_id = 4;
  string language = 5;
  string pace = 6;
  string content_id = 7;
  // The person's confirmation for THIS use: "This voice is yours. You confirm you
  // are the speaker." Must be true.
  bool confirmed_own_voice = 8;
}

docs/api-reference/ai-and-platform/.body:
AI and platform

Model access, the agent-activity feed, sign-in, the business profile and
self-healing status. Package pulse.v1; the least role of each method is in
its table.
Notes

ModelService is the door to the platform's own inference plane. There is
no third-party model behind it.
ActivityService. A subscriber receives only its own runs; a run no
account started (a schedule, an inbound message) reaches nobody. Render
nothing for an unknown non-empty AgentStep.code, never the raw token; an
empty code is valid, so fall back to thought and action. See
Agent activity.
IdentityService. expires_in is in seconds. Refresh, Google sign-in and
sign-out are plain HTTP; see HTTP endpoints.


ModelService
AI model service — completions from the platform's own model.
pulse.v1.ModelService, declared in pulse.proto.



Method
Request → Response
Least role
Notes




Complete
CompleteRequest → stream StreamChunk
editor
Complete streams a completion from the platform's own model.


GetModelStatus
google.protobuf.Empty → ModelStatus
none (public)
GetModelStatus returns current model health/readiness.


SynthesizeSpeech
SynthesizeSpeechRequest → SynthesizeSpeechResponse
viewer
SynthesizeSpeech turns text into spoken audio and returns the WAV bytes. Returns Unavailable when voice output is disabled.


ConfirmAssistantAction
ConfirmAssistantActionRequest → stream AssistantActionEvent
editor
ConfirmAssistantAction runs a proposal the assistant made in Complete, after the user tapped Confirm. The server re-checks the caller's role and the stored arguments; an expired, used or someone else's proposal is refused. Nothing here sends email, posts or calls.



Also uses StreamChunk, AssistantToolEvent, AssistantProposal.
message ConfirmAssistantActionRequest {
  string proposal_id = 1;
}

message AssistantActionEvent {
  string status = 1;       // running | done
  string detail = 2;       // a progress line from the action, or its result
  string route = 3;        // the page that shows the result
  string audit_domain = 4; // set when an audit started: the chat shows its progress card
  string result_id = 5;    // id of the record created or changed, when there is one
}

message SynthesizeSpeechRequest {
  string text = 1;
  string voice = 2; // optional voice id; the default voice when empty
  // What the speech is for: "readback" (the default when empty), "call" or
  // "podcast". Any other value is InvalidArgument. When the asked voice
  // cannot be used for the purpose, another voice of the same language
  // speaks and the response says so.
  string purpose = 3;
  // BCP-47 language of the text (en, fr, es, pt). Used to pick a
  // replacement voice of the same language when one is needed.
  string language = 4;
  // The persona speaking (market-analyst, content-creator, copywriter,
  // strategy-agent, radar-agent, assistant, a built-in twin id). With no voice
  // set, the server speaks in that persona's voice.
  string persona = 5;
}

message SynthesizeSpeechResponse {
  bytes audio = 1;
  string format = 2; // e.g. "wav"
  string voice_used = 3;    // the voice that spoke it (empty = the default voice)
  bool voice_replaced = 4;  // true when the asked voice could not be used and voice_used stands in for it
}

message ChatMessage {
  string role = 1;    // "system", "user", "assistant"
  string content = 2;
  // Text files the person attached to THIS question (logs, exports), on the
  // latest user message only. Treated as untrusted data: credentials are
  // hidden and the content is never followed as instructions. The server
  // refuses a request over a limit.
  repeated ChatAttachment attachments = 3;
  // Pictures (screenshots, photos of a screen or a page) the person attached to
  // THIS question, on the latest user message only. Treated as untrusted:
  // each is re-encoded without metadata and described, credentials are
  // hidden and the description is never followed as instructions.
  // Nothing is stored. At most 3; each at most 1 MiB, all
  // together at most 2500 KiB; a request over a limit is refused with a sentence.
  repeated ChatImage images = 4;
}

// ChatImage is one attached picture: JPEG or PNG bytes.
message ChatImage {
  string name = 1;
  string mime = 2;
  bytes data = 3;
}

// ChatAttachment is one attached text file.
message ChatAttachment {
  string name = 1;
  string text = 2;
}

message CompleteRequest {
  string prompt = 1;                   // simple prompt (use messages for multi-turn)
  repeated ChatMessage messages = 2;   // multi-turn conversation
  double temperature = 3;
  double top_p = 4;
  int32 max_tokens = 5;
  string agent_id = 6;                // which agent profile to use
  // Variables substituted into the agent's prompt template ({{.key}} syntax).
  map template_vars = 7;
}

message ModelStatus {
  bool ready = 1;
  string model_name = 2;
  int64 context_size = 3;
  int32 active_requests = 4;
  double uptime_seconds = 5;
  string error = 6;
}

ActivityService
ActivityService shows what the CALLER's agents are doing right now, across every page and tab, not only the one that started them.
A caller receives only runs started by their own authenticated identity. Runs with no owner (for example scheduled work) are delivered to nobody. The session field is a filter within the caller's own runs, never authorisation.
pulse.v1.ActivityService, declared in activity.proto.



Method
Request → Response
Least role
Notes




SubscribeAgentActivity
SubscribeAgentActivityRequest → stream SubscribeAgentActivityResponse
viewer
SubscribeAgentActivity streams agent runs and their steps as they happen. On subscribe it first replays the current state: every in-flight run, each with the steps recorded so far, then a snapshot_complete event, then live events. A client that opens the page mid-run therefore sees the run.


ListFeaturedMessages
ListFeaturedMessagesRequest → ListFeaturedMessagesResponse
viewer
ListFeaturedMessages returns the operator-curated messages shown in the app's rotating strip (sponsor and partner copy). They can change without a new app release.



message SubscribeAgentActivityRequest {
  // Cap on how many trailing steps the initial replay carries per run. 0 uses
  // the server default.
  int32 replay_steps_per_run = 1;

  // Show only those of the caller's OWN runs belonging to this session.
  //
  // Empty here falls back to the caller's `x-agent-trace-id` metadata. With
  // BOTH absent the subscription is every run the caller owns, never anyone
  // else's. A run with no session is not seen by a client that sets one.
  string session = 2;
}

enum AgentRunStatus {
  AGENT_RUN_STATUS_UNSPECIFIED = 0;
  AGENT_RUN_STATUS_RUNNING = 1;
  AGENT_RUN_STATUS_DONE = 2;
  AGENT_RUN_STATUS_FAILED = 3;
}

// AgentStep is one unit of agent work.
//
// `thought` is often empty: a renderer must not assume every step narrates
// itself.
message AgentStep {
  string run_id = 1;
  int32 index = 2;
  string thought = 3;
  string action = 4;
  string input = 5;
  string result = 6;
  string model = 7;
  int64 latency_ms = 8;
  string error = 9;
  int64 at_unix = 10;
  int64 total_tokens = 11;

  // The step's stable, machine-readable kind, for example "STEP_DISPATCHED".
  // Use it, not a sentence, to word the step in the client's own language.
  //
  // Empty is valid: a renderer falls back to thought/action. An unknown
  // non-empty code must render nothing, never the raw token.
  string code = 12;

  // The facts the code declares, as strings. A missing operand should degrade
  // the rendered line, never drop the step. Some values are data (a quoted
  // example, a caller's URL, the model's own words): show them verbatim and
  // never translate them.
  map operands = 13;

  // How the answer this step reports was produced. Absent when the step has
  // none. A fresh answer needs no mention; a reused, offline or degraded
  // answer is worth showing.
  StepProvenance provenance = 14;
}

// StepProvenance says how a step's answer was obtained.
message StepProvenance {
  // How it was obtained: "fresh" | "exact-cache" | "near-dup" | "offline".
  // Unknown values must degrade to "no claim", never render raw.
  string source = 1;
  // Diagnostic detail for a tooltip; never the primary label.
  string path = 2;
  // Produced without full capability. A reader should weight it lower.
  bool degraded = 3;
  // When the underlying value was produced. For a REUSED result this is the
  // ORIGINAL computation time. Zero means unknown, not "now".
  int64 computed_at_unix = 4;
}

message AgentRun {
  string run_id = 1;
  // The agent's id, e.g. "pulse:whitepaper".
  string agent = 2;
  string session = 3;
  int64 started_unix = 4;
  // Zero while the run is still in flight.
  int64 ended_unix = 5;
  AgentRunStatus status = 6;
  int32 step_count = 7;
  // Populated only on the initial replay, bounded by replay_steps_per_run.
  repeated AgentStep steps = 8;
  string error = 9;
}

message SubscribeAgentActivityResponse {
  oneof event {
    AgentRun snapshot = 1;
    // Marks the end of the replay. A client should render nothing until it
    // arrives.
    bool snapshot_complete = 2;
    AgentRun run_started = 3;
    AgentStep step = 4;
    AgentRun run_finished = 5;
  }
}

message ListFeaturedMessagesRequest {}

// FeaturedMessage is one operator-curated card in the app's rotating strip:
// sponsor and partner copy. It is not localized through the app's own
// catalogue; use `locale` to pick.
message FeaturedMessage {
  string id = 1;
  string title = 2;
  string body = 3;
  // BCP-47 tag, e.g. "en", "pt-BR". Empty means "any locale".
  string locale = 4;
  // Optional link target. The client decides whether to make the card tappable.
  string href = 5;
  // Optional icon hint: a semantic name the client maps to its own icon set,
  // never a URL.
  string icon = 6;
}

message ListFeaturedMessagesResponse {
  repeated FeaturedMessage messages = 1;
  // Where the messages were read from, for diagnosing an empty strip. The
  // client must not parse it.
  string source = 2;
}

