  repeated ConscienceVerdict verdicts = 1;
  string next_page_token = 2;
}

message ConsciencePersona {
  string id = 1;
  string name = 2;
  repeated ConscienceRule rules = 3;
  repeated string gates = 4;
  google.protobuf.Timestamp created = 5;
  int32 version = 6;
  string pending_change_id = 7;
  repeated string pending_reasons = 8;
  repeated ConsciencePersonaVersion versions = 9;
}

message ListConsciencePersonasResponse {
  repeated ConsciencePersona personas = 1;
  int32 max = 2;
  // The application persona every account sits under (read only).
  ConscienceAppPersona app = 3;
}

// The application persona: its name and its limits in plain words.
message ConscienceAppPersona {
  string id = 1;
  string name = 2;
  repeated string rules = 3;
}

message DeleteConsciencePersonaRequest {
  string id = 1;
}

// A set's lifecycle (owner, 2026-11-24). A set can only ADD rules. A change
// that loosens what a set allows, or that removes a rule or a gate from it,
// is not applied: it waits as a pending change until a SECOND person (an
// editor or administrator who did not ask for it) approves it. Nothing
// approves its own change, and every act is kept in an append-only log.
//
// Fields added to ConsciencePersona (all additive):
//   version           the version in force (1 = the first)
//   pending_change_id set when the save you just made is waiting for approval
//   pending_reasons   why it waits, in plain words
//   versions          the versions kept, newest last (for "go back")
message ConsciencePersonaVersion {
  int32 n = 1;
  google.protobuf.Timestamp at = 2;
  bool current = 3;
  // True when a second person approved this version.
  bool approved = 4;
}

message RollbackPersonaRequest {
  string id = 1;
  int32 to_version = 2;
}

// The answer to a change that may wait: decision is "applied" or "pending".
message PersonaChangeResult {
  string decision = 1;
  // The set as it is in force now (unchanged while the change waits).
  ConsciencePersona persona = 2;
  string pending_change_id = 3;
  repeated string reasons = 4;
}

// One change that waits for a second person.
message PersonaChange {
  string id = 1;
  // The account the set belongs to ("" = yours).
  string account_id = 2;
  // A short label of another account (its e-mail), set only on a change of
  // another account that an administrator of this instance may decide.
  string account_label = 3;
  string persona_id = 4;
  string persona_name = 5;
  string act = 6; // update | rollback
  repeated string reasons = 7;
  google.protobuf.Timestamp requested_at = 8;
  google.protobuf.Timestamp expires_at = 9;
  // You asked for this change: someone else must decide it.
  bool proposed_by_you = 10;
  // You may approve or reject it (you are an editor or administrator and not
  // the one who asked, and it has not expired).
  bool can_decide = 11;
  bool expired = 12;
  // The set as it would be if the change were approved.
  ConsciencePersona proposed = 13;
}

message ListPersonaChangesResponse {
  repeated PersonaChange changes = 1;
}

message DecidePersonaChangeRequest {
  string id = 1;
  // "" = your own account; another account only for an administrator.
  string account_id = 2;
  bool approve = 3;
  string reason = 4;
}

message DecidePersonaChangeResponse {
  // applied | rejected
  string decision = 1;
  ConsciencePersona persona = 2;
}

