message GetActionTraceRequest {
  string action_id = 1;
  // Only the steps recorded after this one (0 = all): how a screen follows an action that is still running.
  int32 after_seq = 2;
}

message ListActionTracesRequest {
  // email | message | publish | schedule | call | meeting; "" = all.
  string gate = 1;
  google.protobuf.Timestamp since = 2;
  int32 limit = 3;
  // sent | withheld | failed | published | scheduled | placed | held | refused | open; "" = all.
  string outcome = 4;
  google.protobuf.Timestamp until = 5;
  // The next_page_token of the previous answer; "" = the first page.
  string page_token = 6;
}

message ListActionTracesResponse {
  repeated ActionTrace traces = 1;
  // "" when there are no more.
  string next_page_token = 2;
  // Actions the person marked as not what they expected, this calendar month (UTC).
  int32 flagged_this_month = 3;
}

message ActionTrace {
  string action_id = 1;
  string gate = 2;
  repeated ConscienceEvent events = 3;
  // The highest step recorded for the action, whatever after_seq asked for.
  int32 last_seq = 4;
  // How it ended (the outcome codes above); "" while it is still open.
  string outcome = 5;
  // Set when the action has ended.
  bool finished = 6;
  // What was kept from this action is in what PULSE remembers (read by GetActionTrace only).
  bool remembered = 7;
  // The person marked it as not what they expected.
  bool flagged = 8;
}

message RecordTraceFeedbackRequest {
  string action_id = 1;
  // wrong_rule | wrong_persona | should_have_asked | should_have_blocked | other_noted
  string code = 2;
}

message RecordTraceFeedbackResponse {
  string feedback_id = 1;
  // The same words were already recorded for this action: nothing was added.
  bool already_recorded = 2;
  int32 flagged_this_month = 3;
}

message ActionMemoryRequest {
  string action_id = 1;
}

message ActionMemoryResponse {
  string knowledge_id = 1;
  // True after RememberFromAction, false after ForgetFromAction.
  bool remembered = 2;
  // It already was in that state: nothing changed.
  bool unchanged = 3;
}

// One recorded step of an action.
message ConscienceEvent {
  int32 schema_version = 1;
  string action_id = 2;
  int32 seq = 3;
  google.protobuf.Timestamp at = 4;
  string source = 5;
  ConscienceTracePersona persona = 6;
  string stage = 7;
  string code = 8;
  map params = 9;
  // fact | unable_to_judge | error
  string kind = 10;
  // The records this step refers to.
  repeated string facts_ref = 11;
  string rule_id = 12;
  // allow | warn | block
  string verdict = 13;
  repeated ConscienceKnowledgeRef knowledge = 14;
  repeated ConscienceOption options = 15;
  string needs_approval_from = 16;
  string outcome = 17;
  string plain_text = 18;
}

message ConscienceTracePersona {
  string id = 1;
  string name = 2;
  repeated string domain_words = 3;
}

message ConscienceKnowledgeRef {
  string id = 1;
  // stated | edited | noticed
  string origin = 2;
  // low | medium | high
  string band = 3;
  bool contradicted = 4;
  // A catalogue code saying what the entry is about; the app turns it into a
  // sentence. Never the entry's own text.
  string code = 5;
  // Counts and codes only.
  map params = 6;
}

message ConscienceOption {
  string id = 1;
  string code = 2;
  map params = 3;
  bool dropped = 4;
  string reason_code = 5;
  bool chosen = 6;
  // low | medium | high
  string cost = 7;
  // low | medium | high
  string risk = 8;
  bool reversible = 9;
  // True only when reversible was recorded; otherwise reversible means nothing.
  bool reversible_known = 10;
}

// WHY IT WASN'T SENT (the ledger). Ids, kinds, states and reason codes only: never a body, an address or a name.
message ListNotSentRequest {
  // "" = everything not sent (waiting, held, withheld, failed); sent | waiting | held | withheld | failed | all.
  string state = 1;
  // One reason code of the closed list ("" = all).
  string reason = 2;
  // One channel as the rows name it ("" = all).
  string channel = 3;
  // Acts at or after this time (default: 30 days back; never earlier than 90 days).
  google.protobuf.Timestamp since = 4;
  // Acts before this time (default: no upper bound, so what is scheduled still shows).
  google.protobuf.Timestamp until = 5;
  // At most this many rows (default 50, at most 100).
  int32 limit = 6;
  // The next_page_token of the previous answer; "" = the first page.
  string page_token = 7;
}

message ListNotSentResponse {
  repeated NotSentRow rows = 1;
  // "" when there are no more.
  string next_page_token = 2;
  // Rows per reason under the state, channel and date filters (the chips).
  repeated NotSentCount reason_counts = 3;
  // Rows per state under the reason, channel and date filters.
  repeated NotSentCount state_counts = 4;
  // Rows under every filter.
  int32 total = 5;
  // Sources that could not be read: their acts are NOT MEASURED, never zero.
  repeated string unread_sources = 6;
  // Sources with more recent acts than the ledger reads: older ones are not listed.
  repeated string capped_sources = 7;
}

// One act PULSE considered.
message NotSentRow {
  // Stable id of the row, a kind and a record id joined by a colon (opaque to the app).
  string id = 1;
  // post | reply | dm | auto_reply | message | email | meeting | acknowledgement | pitch_reply | call | owner_reach
  string kind = 2;
  // The channel as the record names it (instagram, linkedin, email, whatsapp, sms, app); "" when the record has none.
  string channel = 3;
  google.protobuf.Timestamp at = 4;
  // sent | waiting | held | withheld | failed
  string state = 5;
  // One code of the closed reason list; the app says each from its own arbs.
  string reason = 6;
  // content | lead | partner_pitch | engagement; "" when no screen shows the record.
  string record_kind = 7;
  string record_id = 8;
  // The conscience record ("What was checked"); "" when none was made or kept.
  string action_id = 9;
}

message NotSentCount {
  string code = 1;
  int32 count = 2;
}

