  repeated KnowledgeEntry entries = 1;
}

message KnowledgeEntry {
  string id = 1;
  // fact | capability | pitfall
  string kind = 2;
  // The plain-language statement.
  string statement = 3;
  // high | medium | low
  string confidence_band = 4;
  // 0 to 1.
  double confidence = 5;
  // stated | observed | inferred
  string origin = 6;
  // How many recorded observations support it.
  int32 evidence_count = 7;
  // How many observations said something different.
  int32 contradicted = 8;
  google.protobuf.Timestamp first_seen = 9;
  google.protobuf.Timestamp last_seen = 10;
  // Days after which the entry counts for half as much.
  double half_life_days = 11;
  // How much of its weight is left, 0 to 1.
  double freshness = 12;
  // active | contested | stale | retired
  string state = 13;
  // Why a person forgot it (state retired).
  string forgotten_reason = 14;
  // A person corrected it.
  bool corrected = 15;
  // Read in from an Open Knowledge Format bundle and not yet confirmed by a
  // person: it counts for little until you correct it (Edit confirms it).
  bool imported = 16;
}

message GetLearningStatusRequest {}

message LearningStatus {
  // Weekly learning is on for this account. Default false.
  bool enabled = 1;
  // The settings (environment names) the deployment has not set, so nothing
  // can be learned yet. Empty = configured.
  repeated string missing = 2;
  // The span of results read each week, and the outcomes a result needs
  // before it is learned from (from the deployment's configuration).
  int32 window_days = 3;
  int32 min_evidence = 4;
  // How many entries are kept, and when the newest was last confirmed.
  int32 entry_count = 5;
  google.protobuf.Timestamp last_learned_at = 6;
  // What the last idle-time tidy-up did, when it found or changed something
  // (counts only; unset when there is nothing to say). Entries it retired stay
  // listed as forgotten and a correction restores them; entries a person
  // corrected or forgot are never touched.
  google.protobuf.Timestamp sleep_at = 7;
  // Entries retired because they were not confirmed for a long time.
  int32 sleep_retired_stale = 8;
  // Entries retired because the same statement was recorded twice.
  int32 sleep_retired_duplicate = 9;
  // Entries whose evidence disagrees: reported, left as they are.
  int32 sleep_contested = 10;
  // Drafting from what was learned: the caller switched "Use what PULSE learned
  // when drafting" on (default false). It takes effect only while weekly
  // learning is also on.
  bool use_in_drafts = 11;
  // How many entries a draft may use today: active, not imported-unconfirmed, at
  // or above the confidence floor. 0 = no learned facts yet (never read as a
  // measured zero).
  int32 draft_ready = 12;
}

message SetLearningRequest {
  bool enabled = 1;
}

message SetDraftingRequest {
  bool enabled = 1;
}

message ForgetKnowledgeRequest {
  string id = 1;
  // Optional.
  string reason = 2;
}

message EditKnowledgeRequest {
  string id = 1;
  // The corrected statement, in plain words (no links, addresses or numbers to call).
  string statement = 2;
  // Optional.
  string reason = 3;
}

message EraseKnowledgeRequest {
  // Must be true: the screen asks the person to confirm first.
  bool confirm = 1;
}

message EraseKnowledgeResponse {
  int32 deleted = 1;
}

message GetKnowledgeNoteRequest {
  // What the note is for (a plan action's title or finding).
  string topic = 1;
}

message KnowledgeNote {
  // Empty when nothing relevant has been learned.
  repeated KnowledgeNoteLine lines = 1;
}

message KnowledgeNoteLine {
  string statement = 1;
  string confidence_band = 2;
}

message ExportKnowledgeRequest {}

message ExportKnowledgeResponse {
  // The bundle (a ZIP) at a signed link that expires within the hour.
  DownloadFile file = 1;
  // How many entries it holds. Entries you forgot are not exported.
  int32 entries = 2;
  // The earliest time the next export is possible (one an hour).
  google.protobuf.Timestamp next_export_at = 3;
}

message ImportKnowledgeRequest {
  // The bundle as a ZIP (at most 1 MiB; a request over a limit is refused).
  bytes bundle = 1;
}

// What an import did, in counts. Refusals are errors with an ErrorInfo reason
// (OKF_*) the app turns into a sentence in the person's language.
message ImportKnowledgeResponse {
  // Entries added, all not yet confirmed.
  int32 imported = 1;
  // Concepts left out because their text holds a link, address, phone number or is too long.
  int32 skipped_text = 2;
  // Concepts left out because you already corrected or forgot that entry, or it is already kept.
  int32 skipped_already_kept = 3;
  // Concepts left out for any other reason (deprecated, not a claim, no usable name).
  int32 skipped_other = 4;
  // Concepts left out because the limit on imported entries was reached.
  int32 skipped_over_limit = 5;
}

